sub_01M2YY33CJG9TFP0K5M42QFN6A	1	sssp-hpc	kernel	{"source": "#include <cstdint>\\n#include <queue>\\n#include <vector>\\n\\nvoid calculate(uint32_t n, uint32_t m, uint32_t *edges, uint64_t *dis)\\n{\\n    std::vector<uint32_t> head(n + 1, 0), cursor(n), to(m), w(m);\\n    for (uint32_t i = 0; i < m; ++i) head[edges[i * 3] + 1]++;\\n    for (uint32_t u = 0; u < n; ++u) head[u + 1] += head[u];\\n    for (uint32_t u = 0; u < n; ++u) cursor[u] = head[u];\\n    for (uint32_t i = 0; i < m; ++i) {\\n        uint32_t u = edges[i * 3], p = cursor[u]++;\\n        to[p] = edges[i * 3 + 1];\\n        w[p] = edges[i * 3 + 2];\\n    }\\n    using item = std::pair<uint64_t, uint32_t>;\\n    std::priority_queue<item, std::vector<item>, std::greater<item>> pq;\\n    std::vector<uint8_t> done(n, 0);\\n    pq.push({0, 0});\\n    while (!pq.empty()) {\\n        auto [d, u] = pq.top(); pq.pop();\\n        if (done[u]) continue;\\n        done[u] = 1;\\n        for (uint32_t i = head[u]; i < head[u + 1]; ++i) {\\n            uint32_t v = to[i]; uint64_t nd = d + w[i];\\n            if (nd < dis[v]) { dis[v] = nd; pq.push({nd, v}); }\\n        }\\n    }\\n}", "language": "cpp"}	\N	interactive2	\N	completed	{"score": 43, "status": "partial", "accepted": false, "maxScore": 50}	{"tests": [{"name": "1e5 点 / 2e5 边", "time": 30, "score": 13, "memory": 9704, "status": "partial", "message": "n=100000 m=200000，耗时 13.9 ms（目标 5.0 ms）", "maxScore": 20}, {"name": "1e5 点 / 1e6 边", "time": 110, "score": 20, "memory": 28472, "status": "accepted", "message": "n=100000 m=1000000，耗时 49.7 ms（目标 60.0 ms）", "maxScore": 20}, {"name": "1e6 点 / 2e6 边", "time": 920, "score": 10, "memory": 73964, "status": "accepted", "message": "n=1000000 m=2000000，耗时 445.3 ms（目标 1200.0 ms）", "maxScore": 10}], "message": "1e5 点 / 2e5 边：n=100000 m=200000，耗时 13.9 ms（目标 5.0 ms）\\n1e5 点 / 1e6 边：n=100000 m=1000000，耗时 49.7 ms（目标 60.0 ms）\\n1e6 点 / 2e6 边：n=1000000 m=2000000，耗时 445.3 ms（目标 1200.0 ms）"}	interactive2-1.0.0	\N	2026-09-20 08: