sub_01M2YY4C23MXJQ9YA5WDS3RR7D	1	sssp-hpc	kernel	{"source": "#include <vector>\\n#include <algorithm>\\n#include <cstdint>\\n#include <queue>\\n#include <omp.h>\\nextern const uint64_t MAX_WEIGHT;\\nextern const uint64_t INF;\\nvoid calculate(uint32_t n, uint32_t m, uint32_t *edges, uint64_t *dis)\\n{\\n    struct edge { uint64_t nxt, to, w; };\\n    edge *e = new edge[m];\\n    uint64_t *head = new uint64_t[n];\\n    std::fill(head, head + n, 0);\\n    for (int i = 0; i < m; ++i) {\\n        uint64_t u = edges[i * 3], v = edges[i * 3 + 1], w = edges[i * 3 + 2];\\n        e[i] = (edge){head[u], v, w};\\n        head[u] = i;\\n    }\\n    struct node { uint64_t d, idx; bool operator<(const node &t) const { return d > t.d; } };\\n    uint64_t *vis = new uint64_t[n];\\n    std::fill(vis, vis + n, 0);\\n    std::priority_queue<node> q;\\n    q.push((node){0, 0});\\n    while (!q.empty()) {\\n        uint64_t u = q.top().idx; q.pop();\\n        if (vis[u]) continue;\\n        vis[u] = 1;\\n        for (int i = head[u]; i; i = e[i].nxt) {\\n            uint64_t v = e[i].to, w = e[i].w;\\n            if (dis[v] > dis[u] + w) { dis[v] = dis[u] + w; if (!vis[v]) q.push((node){dis[v], v}); }\\n        }\\n    }\\n    delete[] e; delete[] head;\\n}", "language": "cpp"}	\N	interactive2	\N	completed	{"score": 0, "status": "wrong_answer", "accepted": false, "maxScore": 50}	{"tests": [{"name": "1e5 点 / 2e5 边", "time": 30, "score": 0, "memory": 13308, "status": "wrong_answer", "message": "27797/100000 个距离不对，首个是 dis[1]=36678725（应为 6390314）", "maxScore": 20}, {"name": "1e5 点 / 1e6 边", "time": 230, "score": 0, "memory": 43100, "status": "wrong_answer", "message": "43/100000 个距离不对，首个是 dis[1]=10318372（应为 6390314）", "maxScore": 20}, {"name": "1e6 点 / 2e6 边", "time": 1050, "score": 0, "memory": 108304, "status": "wrong_answer", "message": "277093/1000000 个距离不对，首个是 dis[1]=1000000000000000000（应为 6390314）", "maxScore": 10}], "message": "1e5 点 / 2e5 边：27797/100000 个距离不对，首个是 dis[1]=36678725（应为