                     {\\n                                local_next_q.push_back(v);\\n                                break;\\n                            }\\n                        }\\n                    }\\n                }\\n            }\\n#pragma omp critical\\n            {\\n                next_q.insert(next_q.end(), local_next_q.begin(), local_next_q.end());\\n            }\\n        }\\n        q.swap(next_q);\\n    }\\n}", "language": "cpp"}	54fe1a221c5f5093cf57a404f2ddcf4f	interactive2	\N	completed	{"score": 0, "status": "runtime_error", "accepted": false, "maxScore": 50}	{"tests": [{"name": "1e5 点 / 2e5 边", "time": 0, "score": 0, "memory": 10240, "status": "runtime_error", "message": "libgomp: Thread creation failed: Resource temporarily unavailable", "maxScore": 20}, {"name": "1e5 点 / 1e6 边", "time": 20, "score": 0, "memory": 28928, "status": "runtime_error", "message": "libgomp: Thread creation failed: Resource temporarily unavailable", "maxScore": 20}, {"name": "1e6 点 / 2e6 边", "time": 40, "score": 0, "memory": 73600, "status": "runtime_error", "message": "libgomp: Thread creation failed: Resource temporarily unavailable", "maxScore": 10}], "message": "1e5 点 / 2e5 边：libgomp: Thread creation failed: Resource temporarily unavailable\\n1e5 点 / 1e6 边：libgomp: Thread creation failed: Resource temporarily unavailable\\n1e6 点 / 2e6 边：libgomp: Thread creation failed: Resource temporarily unavailable"}	interactive2-1.0.0	\N	2026-09-20 08:17:45.931+00	2026-09-20 08:17:48.342+00
