\\n        dag.head[u] = 0;\\n    }\\n    for (int i = 2; i <=  n; ++i)\\n    {\\n        if (!idfn[i]) continue;\\n        int t = idfn[i];\\n        if (idom[t] ^ sdom[t]) idom[t] = idom[idom[t]];\\n    }\\n    for (int i = 1; i <= n; ++i) {\\n        dep[i] = -1;\\n    }\\n    dep[s] = 0;\\n    for (int i = 2; i <= n; ++i) {\\n        if (idom[idfn[i]] == 0) continue;\\n        dep[idfn[i]] = dep[idom[idfn[i]]] + 1;\\n    }\\n    for (int i = 1; i <= n; ++i)\\n    {\\n        printf(\\"%d\\\\n\\", dep[i]);\\n    }\\n    return 0;\\n}", "language": "cpp"}	0a33daa1c16cab541a49f2cfd76da40d	interactive	\N	completed	{"score": 30, "status": "partial", "accepted": false, "maxScore": 100}	{"tests": [{"name": "全部子任务", "time": 680, "score": 30, "memory": 48900, "status": "partial", "message": "通过 7/20 个测试点，共 30 分；首个错误：第 8 个测试点（n=100000 m=99999）第 1 行不对（期望 0，得到 (无)）", "maxScore": 100}], "message": "全部子任务：通过 7/20 个测试点，共 30 分；首个错误：第 8 个测试点（n=100000 m=99999）第 1 行不对（期望 0，得到 (无)）"}	interactive-1.0.0	\N	2026-09-24 10:39:39.259+00	2026-09-24 10:39:43.654+00
