sub_01M39ETBYTGYQZ1AYH2SJV34XZ	1	hanoi-kth	divide-and-conquer	{"source": "// Reference solution — hanoi-kth.\\n//\\n// The optimal solution for n disks from `from` to `to` is\\n//   hanoi(n-1, from, via, to) | move from->to | hanoi(n-1, via, to, from)\\n// so step k is located by walking down that decomposition in O(n).\\n#include <cstdio>\\n\\nint main() {\\n    int n;\\n    long long k;\\n    if (scanf(\\"%d %lld\\", &n, &k) != 2) return 0;\\n\\n    char from = 'A', to = 'C', via = 'B';\\n\\n    while (n > 0) {\\n        long long middle = 1LL << (n - 1);\\n\\n        if (k == middle) {\\n            printf(\\"%c %c\\\\n\\", from, to);\\n            return 0;\\n        }\\n\\n        if (k < middle) {\\n            // Descend into hanoi(n-1, from, via, to): the target and the spare swap.\\n            char spare = via;\\n            via = to;\\n            to = spare;\\n        } else {\\n            // Descend into hanoi(n-1, via, to, from): the source and the spare swap.\\n            k -= middle;\\n            char spare = via;\\n            via = from;\\n            from = spare;\\n        }\\n    }\\n\\n    return 0;\\n}\\n", "language": "cpp"}	f53dd2be62c2543a3961b0d6b1abd488	interactive	\N	completed	{"score": 0, "status": "wrong_answer", "accepted": false, "maxScore": 100}	{"tests": [{"name": "全部子任务", "time": 28140, "score": 0, "memory": 3328, "status": "wrong_answer", "message": "首个错误：n=3 k=5 超时（限额 1000 ms）", "maxScore": 100}], "message": "全部子任务：首个错误：n=3 k=5 超时（限额 1000 ms）"}	interactive-1.0.0	\N	2026-09-24 10:19:14.783+00	2026-09-24 10:19:44.966+00
sub_01M39ETEF61RFCH2088Z6MVWN8	1	hanoi-kth	divide-and-conquer	{"source": "// Reference solution — hanoi-kth.\\n//\\n// The optimal solution for n disks from `from` to `to` is\\n//   hanoi(n-1, from, via, to) | move from->to | hanoi(n-1, via, to, from)\\n// so step k is located by walking down that decomposition in O(n).\\n#include <cstdio>\\n\\nint main() {\\n    int n;\\n    long long k;\\n    if (scanf(\\"%d %lld\\", &n, &k) != 2) return 0;\\n\\n    char from = 'A', to = 'C', via = 'B';\\n\\n    while (n > 0) {\\n        long long middle = 1LL << (n - 1);\\n\\n        if (k == middle) {\\n            printf(\\"%c %c\\\\n\\", from, to);\\n            return 0;\\n        }\\n\\n        if (k < middle) {\\n            // Descend into hanoi(n-1, from, via, to): the target and the spare swap.\\n            char spare = via;\\n            via = to;\\n            to = spare;\\n        } else {\\n            // Descend into hanoi(n-1, via, to, from): the source and the spare swap.\\n            k -= middle;\\n            char spare = via;\\n            via = from;\\n            from = spare;\\n        }\\n    }\\n\\n    return 0;\\n}\\n", "language": "cpp"}	6c63fd9062fe63abffb0ecafe4493cac	interactive	\N	completed	{"score": 0, "status": "wrong_answer", "accepted": false, "maxScore": 100}	{"tests": [{"name": "全部子任务", "time": 28080, "score": 0, "memory": 3328, "status": "wrong_answer", "message": "首个错误：n=3 k=5 超时（限额 1000 ms）", "maxScore": 100}], "message": "全部子任务：首个错误：n=3 k=5 超时（限额 1000 ms）"}	interactive-1.0.0	\N	2026-09-24 10:19:17.354+00	2026-09-24 10:20:16.069+00
sub_01M3NRKZGRZ0QQ452X6ZH175X1	1	openmp-pi	kernel	{"source": "#include <bits/stdc++.h>\\nusing namespace std;\\nint main() {\\n    long long n;\\n    cin >> n;\\n    double h = 1.0 / n, sum = 0.0;\\n    for (long long i = 0; i < n; i++) {\\n        double x = (i + 0.5) * h;\\n        sum += 4.0 / (1.0 + x * x);\\n    }\\n    cout << fixed << setprecision(10) << sum * h << endl;\\n    return 0;\\n}", "language": "cpp"}	330c07abb1fcab67d38e00055557fd11	interactive	\N	completed	{"score": 49, "status": "partial", "accepted": false, "maxScore": 100}	{"tests": [{"name": "n = 10^9", "time": 1730, "score": 49, "memory": 3456, "status": "partial", "message": "n=1000000000，你 870.0 ms，串行参考 859.0 ms，加速比 0.99x", "maxScore": 100}], "message": "n = 10^9：n=1000000000，你 870.0 ms，串行参考 859.0 ms，加速比 0.99x"}	interactive-1.0.0	\N	2026-09-29 05:01:24.38+00	2026-09-29 05:01:29.446+00
sub_01M3PWHF2R2MQNSCDKDVXJ0JHG	1	sssp-hpc	kernel	{"source": "#include <vector>\\n#include <cstdint>\\n#include <queue>\\n#include <omp.h>\\n\\nvoid calculate(uint32_t n, uint32_t m, uint32_t *edges, uint64_t *dis)\\n{\\n    struct edge { uint32_t to, w; };\\n    std::vector<edge> e(m);\\n    std::vector<uint32_t> deg(n, 0);\\n    std::vector<uint32_t> offset(n);\\n    std::vector<uint32_t> pos(m);\\n\\n#pragma omp parallel for\\n    for (uint32_t i = 0; i < m; ++i) {\\n        uint32_t u = edges[i * 3];\\n        pos[i] = __atomic_fetch_add(&deg[u], 1, __ATOMIC_RELAXED);\\n    }\\n    offset[0] = 0;\\n    for (int64_t i = 1; i < n; ++i) offset[i] = offset[i - 1] + deg[i - 1];\\n#pragma omp parallel for\\n    for (int64_t i = 0; i < m; ++i) {\\n        uint32_t u = edges[i * 3], v = edges[i * 3 + 1], w = edges[i * 3 + 2];\\n        e[offset[u] + pos[i]] = (edge){v, w};\\n    }\\n\\n    std::vector<uint8_t> vis(n, 0);\\n    std::vector<uint32_t> q;\\n    q.push_back(0);\\n    while (!q.empty()) {\\n        std::vector<uint32_t> next_q;\\n        std::fill(vis.begin(), vis.end(), 0);\\n#pragma omp parallel\\n        {\\n            std::vector<uint32_t> local_next_q;\\n#pragma omp for\\n            for (uint32_t i = 0; i < q.size(); ++i) {\\n                uint32_t u = q[i];\\n                for (uint32_t j = offset[u]; j < offset[u] + deg[u]; ++j) {\\n                    uint32_t v = e[j].to;\\n                    uint64_t new_dis = dis[u] + e[j].w;\\n                    uint64_t old_dis = dis[v];\\n                    while (new_dis < old_dis) {\\n                        if (__atomic_compare_exchange_n(&dis[v], &old_dis, new_dis, false, __ATOMIC_RELAXED, __ATOMIC_RELAXED)) {\\n                            if (__atomic_exchange_n(&vis[v], 1, __ATOMIC_RELAXED) == 0) {\\n                                local_next_q.push_back(v);\\n                                break;\\n                            }\\n                        }\\n                    }\\n                }\\n            }\\n#pragma omp critical\\n            { next_q.insert(next_q.end(), local_next_q.begin(), local_next_q.end()); }\\n        }\\n        q.swap(next_q);\\n    }\\n}", "language": "cpp"}	7786f01442713209599ecf8f072ed2e0	interactive	\N	completed	{"score": 36, "status": "partial", "accepted": false, "maxScore": 50}	{"tests": [{"name": "1e5 点 / 2e5 边", "time": 100, "score": 10, "memory": 13672, "status": "partial", "message": "n=100000 m=200000，耗时 53.0 ms（goal 5.0 ms）", "maxScore": 20}, {"name": "1e5 点 / 1e6 边", "time": 220, "score": 16, "memory": 37680, "status": "partial", "message": "n=100000 m=1000000，耗时 80.2 ms（goal 60.0 ms）", "maxScore": 20}, {"name": "1e6 点 / 2e6 边", "time": 930, "score": 10, "memory": 114364, "status": "accepted", "message": "n=1000000 m=2000000，耗时 91.9 ms（goal 1200.0 ms）", "maxScore": 10}], "message": "1e5 点 / 2e5 边：n=100000 m=200000，耗时 53.0 ms（goal 5.0 ms）\\n1e5 点 / 1e6 边：n=100000 m=1000000，耗时 80.2 ms（goal 60.0 ms）\\n1e6 点 / 2e6 边：n=1000000 m=2000000，耗时 91.9 ms（goal 1200.0 ms）"}	interactive-1.0.0	\N	2026-09-29 15:29:10.749+00	2026-09-29 15:29:15.947+00
