sub_01M34MYDBW3YTV3QS6R7ZXHSDT	1	perf-optimize	kernel	{"source": "#pragma GCC optimize(\\"O3\\")\\n#include <bits/stdc++.h>\\n#include <immintrin.h>\\nusing namespace std;\\n\\nstatic char ibuf[1 << 21];\\nstatic int ilen, iptr;\\ninline int nextInt() {\\n    int x = 0;\\n    while (iptr < ilen && (ibuf[iptr] < '0' || ibuf[iptr] > '9')) ++iptr;\\n    while (iptr < ilen && ibuf[iptr] >= '0' && ibuf[iptr] <= '9')\\n        x = x * 10 + (ibuf[iptr++] - '0');\\n    return x;\\n}\\n\\nstatic char obuf[1 << 22];\\nstatic size_t olen;\\ninline void putInt(int x) {\\n    char tmp[12]; int t = 0;\\n    if (x == 0) tmp[t++] = '0';\\n    while (x) { tmp[t++] = (char)('0' + x % 10); x /= 10; }\\n    while (t) obuf[olen++] = tmp[--t];\\n}\\n\\nvoid gemm(float * __restrict A, float * __restrict B, float * __restrict C, int n) \\n__attribute__((target(\\"avx512f,avx512bw\\")));\\n\\nvoid gemm(float * __restrict A, float * __restrict B, float * __restrict C, int n) {\\n    __m512 B0 = _mm512_loadu_ps(B);\\n    __m512 B1 = _mm512_loadu_ps(B + n);\\n    __m512 B2 = _mm512_loadu_ps(B + 2 * n);\\n    __m512 B3 = _mm512_loadu_ps(B + 3 * n);\\n    __m512 B4 = _mm512_loadu_ps(B + 4 * n);\\n    __m512 B5 = _mm512_loadu_ps(B + 5 * n);\\n    __m512 B6 = _mm512_loadu_ps(B + 6 * n);\\n    __m512 B7 = _mm512_loadu_ps(B + 7 * n);\\n    for (int i = 0; i < 8; ++i) {\\n        float *A_row = A + i * n;\\n        float *C_row = C + i * n;\\n        __m512 vc = _mm512_loadu_ps(C_row);\\n        __m512 va = _mm512_set1_ps(A_row[0]);\\n        vc = _mm512_fmadd_ps(va, B0, vc);\\n        va = _mm512_set1_ps(A_row[1]);\\n        vc = _mm512_fmadd_ps(va, B1, vc);\\n        va = _mm512_set1_ps(A_row[2]);\\n        vc = _mm512_fmadd_ps(va, B2, vc);\\n        va = _mm512_set1_ps(A_row[3]);\\n        vc = _mm512_fmadd_ps(va, B3, vc);\\n        va = _mm512_set1_ps(A_row[4]);\\n        vc = _mm512_fmadd_ps(va, B4, vc);\\n        va = _mm512_set1_ps(A_row[5]);\\n        vc = _mm512_fmadd_ps(va, B5, vc);\\n        va = _mm512_set1_ps(A_row[6]);\\n        vc = _mm512_fmadd_ps(va, B6, vc);\\n        va = _mm512_set1_ps(A_row[7]);\\n        vc = _mm512_fmadd_ps(va, B7, vc);\\n        _mm512_storeu_ps(C_row, vc);\\n    }\\n}\\n\\nint main() {\\n    ios::sync_with_stdio(false);\\n    cin.tie(nullptr);\\n    ilen = (int)fread(ibuf, 1, sizeof ibuf, stdin);\\n    int n = nextInt();\\n    vector<float> a(n*n), b(n*n), c(n*n, 0.0f);\\n    \\n    for (int i = 0; i < n; i++)\\n        for (int j = 0; j < n; j++) {\\n            int x = nextInt();\\n            a[i * n + j] = x;\\n\\t\\t}\\n    for (int i = 0; i < n; i++)\\n        for (int j = 0; j < n; j++) {\\n            int x = nextInt();\\n            b[i * n + j] = x;\\n\\t\\t}\\n    for (int i = 0; i < n; i += 8) {\\n        for (int k = 0; k < n; k += 8) {\\n            for (int j = 0; j < n; j += 16) {\\n                gemm(a.data() + i * n + k, b.data() + k * n + j, c.data() + i * n + j, n);\\n            }\\n        }\\n    }\\n    for (int i = 0; i < n; ++i) {\\n        for (int j = 0; j < n; ++j) {\\n            if (j) obuf[olen++] = ' ';\\n            putInt((int)c[i * n + j]);\\n        }\\n        obuf[olen++] = '\\\\n';\\n    }\\n    fwrite(obuf, 1, olen, stdout);\\n    return 0;\\n}", "language": "cpp"}	f37b3d18eaa6ca112bf5d18ce9c2278c	interactive	\N	completed	{"score": 100, "status": "accepted", "accepted": true, "maxScore": 100}	{"tests": [{"name": "n=512", "time": 370, "score": 100, "memory": 11000, "status": "accepted", "message": "输出正确；用时 9.08 ms，基线 68.60 ms，加速 7.55x", "maxScore": 100}], "message": "n=512：输出正确；用时 9.08 ms，基线 68.60 ms，加速 7.55x"}	interactive-1.0.0	\N	2026-09-22 13:30:06.59+00	2026-09-22 13:30:12.716+00
sub_01M39FSQJY5EW1D36CPWCWC50W	1	dominator-tree	graphs	{"source": "#include <iostream>\\n#include <cstdio>\\n\\nusing namespace std;\\n\\nconst int N = 6e5 + 10;\\nint s;\\n\\nstruct Edge\\n{\\n    int head[N], nxt[N], to[N], tot;\\n\\n    void add(int x, int y)\\n    {\\n        nxt[++tot] = head[x], head[x] = tot, to[tot] = y;\\n    }\\n}g, rg, dag, tr;\\n\\nint n, m;\\nint sdom[N], idom[N], fa[N];\\nint dep[N];\\nint dfn[N], idfn[N], tim, ans[N];\\n\\nstruct bcj\\n{\\n    int fa, mn;\\n\\n}dsu[N];\\n\\nint find(int u)\\n{\\n    if (u == dsu[u].fa) return u;\\n    int tmp = dsu[u].fa;\\n    dsu[u].fa = find(dsu[u].fa);\\n    //int tmp = find(dsu[u].fa);\\n    if (dfn[sdom[dsu[u].mn]] > dfn[sdom[dsu[tmp].mn]]) dsu[u].mn = dsu[tmp].mn;\\n    return dsu[u].fa;\\n}    \\n\\nvoid dfs(int u)\\n{\\n    dfn[u] = ++tim;\\n    idfn[dfn[u]] = u;\\n    for (int i = g.head[u]; i; i = g.nxt[i])\\n    {\\n        int v = g.to[i];\\n        if (dfn[v]) continue;\\n        fa[v] = u;\\n        dfs(v);\\n    }\\n}\\n\\n\\n\\nint main()\\n{\\n    scanf(\\"%d%d%d\\", &n, &m, &s);\\n    for (int i = 1; i <= m; ++i)\\n    {\\n        int u, v;\\n        scanf(\\"%d%d\\", &u, &v);\\n        g.add(u, v);\\n        rg.add(v, u);\\n    }\\n    dfs(s);\\n    for (int i = 1; i <= n; ++i) sdom[i] = dsu[i].fa = dsu[i].mn = i;\\n    for (int id = n; id >= 2; --id)\\n    {\\n        int u = idfn[id];\\n        if (!u) continue;\\n        for (int i = rg.head[u]; i; i = rg.nxt[i])\\n        {\\n            int v = rg.to[i];\\n            if (!dfn[v]) continue;\\n            find(v);\\n            if (dfn[sdom[u]] > dfn[sdom[dsu[v].mn]]) sdom[u] = sdom[dsu[v].mn];\\n        }\\n        dsu[u].fa = fa[u];\\n        dag.add(sdom[u], u);\\n        u = fa[u];//因为不能包括sdom\\n        for (int i = dag.head[u]; i; i = dag.nxt[i])\\n        {\\n            int v = dag.to[i];\\n            find(v);\\n            idom[v] = ((u == sdom[dsu[v].mn]) ? u : dsu[v].mn);\\n        }\\n        dag.head[u] = 0;\\n    }\\n    for (int i = 2; i <=  n; ++i)\\n    {\\n        if (!idfn[i]) continue;\\n        int t = idfn[i];\\n        if (idom[t] ^ sdom[t]) idom[t] = idom[idom[t]];\\n    }\\n    for (int i = 1; i <= n; ++i) {\\n        dep[i] = -1;\\n    }\\n    dep[s] = 0;\\n    for (int i = 2; i <= n; ++i) {\\n        if (idom[idfn[i]] == 0) continue;\\n        dep[idfn[i]] = dep[idom[idfn[i]]] + 1;\\n    }\\n    for (int i = 1; i <= n; ++i)\\n    {\\n        printf(\\"%d\\\\n\\", dep[i]);\\n    }\\n    return 0;\\n}", "language": "cpp"}	274518e41ef6472a881bf5dd8eb4341e	interactive	\N	completed	{"score": 100, "status": "accepted", "accepted": true, "maxScore": 100}	{"tests": [{"name": "全部子任务", "time": 1580, "score": 100, "memory": 48900, "status": "accepted", "message": "全部测试点通过", "maxScore": 100}], "message": "全部子任务：全部测试点通过"}	interactive-1.0.0	\N	2026-09-24 10:36:22.499+00	2026-09-24 10:36:28.428+00
