   va = _mm512_set1_ps(A_row[6]);\\n        vc = _mm512_fmadd_ps(va, B6, vc);\\n        va = _mm512_set1_ps(A_row[7]);\\n        vc = _mm512_fmadd_ps(va, B7, vc);\\n        _mm512_storeu_ps(C_row, vc);\\n    }\\n}\\n\\nint main() {\\n    ios::sync_with_stdio(false);\\n    cin.tie(nullptr);\\n    ilen = (int)fread(ibuf, 1, sizeof ibuf, stdin);\\n    int n = nextInt();\\n    vector<float> a(n*n), b(n*n), c(n*n, 0.0f);\\n    \\n    for (int i = 0; i < n; i++)\\n        for (int j = 0; j < n; j++) {\\n            int x = nextInt();\\n            a[i * n + j] = x;\\n\\t\\t}\\n    for (int i = 0; i < n; i++)\\n        for (int j = 0; j < n; j++) {\\n            int x = nextInt();\\n            b[i * n + j] = x;\\n\\t\\t}\\n    for (int i = 0; i < n; i += 8) {\\n        for (int k = 0; k < n; k += 8) {\\n            for (int j = 0; j < n; j += 16) {\\n                gemm(a.data() + i * n + k, b.data() + k * n + j, c.data() + i * n + j, n);\\n            }\\n        }\\n    }\\n    for (int i = 0; i < n; ++i) {\\n        for (int j = 0; j < n; ++j) {\\n            if (j) obuf[olen++] = ' ';\\n            putInt((int)c[i * n + j]);\\n        }\\n        obuf[olen++] = '\\\\n';\\n    }\\n    fwrite(obuf, 1, olen, stdout);\\n    return 0;\\n}", "language": "cpp"}	e1118ca4b59cc54e9bc847680846d30d	interactive	\N	completed	{"score": 100, "status": "accepted", "accepted": true, "maxScore": 100}	{"tests": [{"name": "n=512", "time": 400, "score": 100, "memory": 10960, "status": "accepted", "message": "输出正确；用时 9.38 ms，基线 72.31 ms，加速 7.71x", "maxScore": 100}], "message": "n=512：输出正确；用时 9.38 ms，基线 72.31 ms，加速 7.71x"}	interactive-1.0.0	\N	2026-09-22 13:30:43.468+00	2026-09-22 13:30:49.95+00
sub_01M34RX4KPKB7EFWW9WQPD4SKP	1	mpi-pi	comm	{"source": "#include <mpi.h>\\n#include <bits/stdc++.h>\\nusing namespace std;\\nint main(int argc, char** argv) {\\n    MPI_Init(&argc, &argv);\\n    int rank, size;\\n    MPI_Comm_rank(MPI_COMM_WORLD, &rank);\\n    MPI_Comm_size(MPI_COMM_WORLD, &size);\\n \\n    long long n = 0;\\n    if (rank == 0) { cin >> n; }\\n    MPI_Bcast(&n, 1, MPI_LONG_LONG, 0, MPI_COMM_WORLD);\\n \\n    double h = 1.0 / n, local = 0.0;\\n    for (long long i = rank; i < n; i += size) {       // 按 rank 分块（strided）\\n        double x = (i + 0.5) * h;\\n        local += 4.0 / (1.0 + x * x);\\n    }\\n \\n    if (rank == 0) {\\n        double total = local;\\n        for (int src = 1; src < size; src++) {          // 逐块点对点收，串行累加\\n            double part;\\n            MPI_Recv(&part, 1, MPI_DOUBLE, src, 0, MPI_COMM_WORLD, MPI_STATUS_IGNORE);\\n            total += part;\\n        }\\n        cout << fixed << setprecision(10) << total * h << endl;\\n    } else {\\n        MPI_Send(&local, 1, MPI_DOUBLE, 0, 0, MPI_COMM_WORLD);\\n    }\\n \\n    MPI_Finalize();\\n    return 0;\\n}", "language": "cpp"}	f798179d172f514ae804442b94886a0d	interactive	\N	completed	{"score": 0, "status": "compile_error", "accepted": false, "maxScore": 100}	{"tests": [{"name": "n=200000000 np=4", "score": 0, "status": "compile_error", "maxScore": 100}], "message": "driver.cpp:62:118: warning: missing terminating \\" character\\n   62 |     printf(\\"FOI_RESULT {\\"score\\":%d,\\"maxScore\\":100,\\"status\\":\\"%s\\",\\"message\\":\\"%s；用时 %.1f ms，基线 %.1f ms，加速 %.2fx\\"}\\n      |                                                                                                                      ^\\ndriver.cpp:62:118: error: missing terminating \\" character\\n   62 |     printf(\\"FOI_RESULT {\\"score\\":%d,\\"maxScore\\":100,\\"status\\":\\"%s\\",\\"message\\":\\"%s；用时 %.1f ms，基线 %.1f ms，加速 %.2fx\\"}\\n      |                                                                