sub_01M3PWK0SMT7EK2QJ9DMS19203	1	sssp-hpc	kernel	{"source": "#include <vector>\\n#include <cstdint>\\n#include <queue>\\n#include <omp.h>\\n\\nvoid calculate(uint32_t n, uint32_t m, uint32_t *edges, uint64_t *dis)\\n{\\n    struct edge\\n    {\\n        uint32_t to, w;\\n    };\\n    std::vector<edge> e(m);\\n\\n    std::vector<uint32_t> deg(n, 0);\\n    std::vector<uint32_t> offset(n);\\n    std::vector<uint32_t> pos(m);\\n\\n#pragma omp parallel for\\n    for (uint32_t i = 0; i < m; ++i)\\n    {\\n        uint32_t u = edges[i * 3];\\n        pos[i] = __atomic_fetch_add(&deg[u], 1, __ATOMIC_RELAXED);\\n    }\\n\\n    offset[0] = 0;\\n    for (int64_t i = 1; i < n; ++i)\\n    {\\n        offset[i] = offset[i - 1] + deg[i - 1];\\n    }\\n\\n#pragma omp parallel for\\n    for (int64_t i = 0; i < m; ++i)\\n    {\\n        uint32_t u = edges[i * 3];\\n        uint32_t v = edges[i * 3 + 1];\\n        uint32_t w = edges[i * 3 + 2];\\n        e[offset[u] + pos[i]] = (edge){v, w};\\n    }\\n\\n    std::vector<uint8_t> vis(n, 0);\\n    std::vector<uint32_t> q;\\n    q.push_back(0);\\n\\n    while (!q.empty())\\n    {\\n        std::vector<uint32_t> next_q;\\n        std::fill(vis.begin(), vis.end(), 0);\\n#pragma omp parallel\\n        {\\n            std::vector<uint32_t> local_next_q;\\n#pragma omp for\\n            for (uint32_t i = 0; i < q.size(); ++i)\\n            {\\n                uint32_t u = q[i];\\n                for (uint32_t j = offset[u]; j < offset[u] + deg[u]; ++j)\\n                {\\n                    uint32_t v = e[j].to;\\n                    uint64_t new_dis = dis[u] + e[j].w;\\n                    uint64_t old_dis = dis[v];\\n                    while (new_dis < old_dis)\\n                    {\\n                        if (__atomic_compare_exchange_n(&dis[v], &old_dis, new_dis, false, __ATOMIC_RELAXED, __ATOMIC_RELAXED))\\n                        {\\n                            if (__atomic_exchange_n(&vis[v], 1, __ATOMIC_RELAXED) == 0)\\n                            {\\n                                local_next_q.push_back(v);\\n                                break;\\n                            }\\n                        }\\n                    }\\n                }\\n            }\\n#pragma omp critical\\n            {\\n                next_q.insert(next_q.end(), local_next_q.begin(), local_next_q.end());\\n            }\\n        }\\n        q.swap(next_q);\\n    }\\n}", "language": "cpp"}	b766b6e308c03e8e36354eab3b3ee3b0	interactive	\N	completed	{"score": 42, "status": "partial", "accepted": false, "maxScore": 50}	{"tests": [{"name": "1e5 点 / 2e5 边", "time": 70, "score": 12, "memory": 13652, "status": "partial", "message": "n=100000 m=200000，耗时 17.7 ms（goal 5.0 ms）", "maxScore": 20}, {"name": "1e5 点 / 1e6 边", "time": 190, "score": 20, "memory": 37896, "status": "accepted", "message": "n=100000 m=1000000，耗时 50.1 ms（goal 60.0 ms）", "maxScore": 20}, {"name": "1e6 点 / 2e6 边", "time": 960, "score": 10, "memory": 114652, "status": "accepted", "message": "n=1000000 m=2000000，耗时 115.0 ms（goal 1200.0 ms）", "maxScore": 10}], "message": "1e5 点 / 2e5 边：n=100000 m=200000，耗时 17.7 ms（goal 5.0 ms）\\n1e5 点 / 1e6 边：n=100000 m=1000000，耗时 50.1 ms（goal 60.0 ms）\\n1e6 点 / 2e6 边：n=1000000 m=2000000，耗时 115.0 ms（goal 1200.0 ms）"}	interactive-1.0.0	\N	2026-09-29 15:30:01.654+00	2026-09-29 15:30:05.551+00
