sub_01M39FTYHGVPMPQPBNRBKMZBQZ	1	dominator-tree	graphs	{"source": "#include <iostream>\\n#include <cstdio>\\n\\nusing namespace std;\\n\\nconst int N = 6e5 + 10;\\nint s;\\n\\nstruct Edge\\n{\\n    int head[N], nxt[N], to[N], tot;\\n\\n    void add(int x, int y)\\n    {\\n        nxt[++tot] = head[x], head[x] = tot, to[tot] = y;\\n    }\\n}g, rg, dag, tr;\\n\\nint n, m;\\nint sdom[N], idom[N], fa[N];\\nint dfn[N], idfn[N], tim, ans[N];\\n\\nstruct bcj\\n{\\n    int fa, mn;\\n\\n}dsu[N];\\n\\nint find(int u)\\n{\\n    if (u == dsu[u].fa) return u;\\n    int tmp = dsu[u].fa;\\n    dsu[u].fa = find(dsu[u].fa);\\n    //int tmp = find(dsu[u].fa);\\n    if (dfn[sdom[dsu[u].mn]] > dfn[sdom[dsu[tmp].mn]]) dsu[u].mn = dsu[tmp].mn;\\n    return dsu[u].fa;\\n}    \\n\\nvoid dfs(int u)\\n{\\n    dfn[u] = ++tim;\\n    idfn[dfn[u]] = u;\\n    for (int i = g.head[u]; i; i = g.nxt[i])\\n    {\\n        int v = g.to[i];\\n        if (dfn[v]) continue;\\n        fa[v] = u;\\n        dfs(v);\\n    }\\n}\\n\\n\\n\\nint main()\\n{\\n    scanf(\\"%d%d%d\\", &n, &m, &s);\\n    for (int i = 1; i <= m; ++i)\\n    {\\n        int u, v;\\n        scanf(\\"%d%d\\", &u, &v);\\n        g.add(u, v);\\n        rg.add(v, u);\\n    }\\n    dfs(s);\\n    for (int i = 1; i <= n; ++i) sdom[i] = dsu[i].fa = dsu[i].mn = i;\\n    for (int id = n; id >= 2; --id)\\n    {\\n        int u = idfn[id];\\n        if (!u) continue;\\n        for (int i = rg.head[u]; i; i = rg.nxt[i])\\n        {\\n            int v = rg.to[i];\\n            if (!dfn[v]) continue;\\n            find(v);\\n            if (dfn[sdom[u]] > dfn[sdom[dsu[v].mn]]) sdom[u] = sdom[dsu[v].mn];\\n        }\\n        dsu[u].fa = fa[u];\\n        dag.add(sdom[u], u);\\n        u = fa[u];//因为不能包括sdom\\n        for (int i = dag.head[u]; i; i = dag.nxt[i])\\n        {\\n            int v = dag.to[i];\\n            find(v);\\n            idom[v] = ((u == sdom[dsu[v].mn]) ? u : dsu[v].mn);\\n        }\\n        dag.head[u] = 0;\\n    }\\n    for (int i = 2; i <=  n; ++i)\\n    {\\n        if (!idfn[i]) continue;\\n        int t = idfn[i];\\n        if (idom[t] ^ sdom[t]) idom[t] = idom[idom[t]];\\n    }\\n    for (int i = n; i >= 2; --i)\\n    {\\n        if (!idfn[i]) continue;\\n        ans[idom[idfn[i]]] += ++ans[idfn[i]];\\n    }\\n    ++ans[1];\\n    for (int i = 1; i <= n; ++i)\\n    {\\n        printf(\\"%d \\", ans[i]);\\n    }\\n    return 0;\\n}", "language": "cpp"}	7501b203fbe2f104c30e3d260ba74fb8	interactive	\N	completed	{"score": 0, "status": "wrong_answer", "accepted": false, "maxScore": 100}	{"tests": [{"name": "全部子任务", "time": 2200, "score": 0, "memory": 57348, "status": "wrong_answer", "message": "首个错误：第 1 个测试点（n=6 m=8）第 1 行不对（期望 0，得到 6）", "maxScore": 100}], "message": "全部子任务：首个错误：第 1 个测试点（n=6 m=8）第 1 行不对（期望 0，得到 6）"}	interactive-1.0.0	\N	2026-09-24 10:37:02.39+00	2026-09-24 10:37:07.985+00
