 (int i = 2; i <=  n; ++i)\\n    {\\n        if (!idfn[i]) continue;\\n        int t = idfn[i];\\n        if (idom[t] ^ sdom[t]) idom[t] = idom[idom[t]];\\n    }\\n    for (int i = n; i >= 2; --i)\\n    {\\n        if (!idfn[i]) continue;\\n        ans[idom[idfn[i]]] += ++ans[idfn[i]];\\n    }\\n    ++ans[1];\\n    for (int i = 1; i <= n; ++i)\\n    {\\n        printf(\\"%d \\", ans[i]);\\n    }\\n    return 0;\\n}", "language": "cpp"}	4ae49d30960b86a9314504dc36fb2de7	interactive	\N	completed	{"score": 0, "status": "wrong_answer", "accepted": false, "maxScore": 100}	{"tests": [{"name": "全部子任务", "time": 1500, "score": 0, "memory": 57344, "status": "wrong_answer", "message": "首个错误：第 1 个测试点（n=6 m=8）第 1 行不对（期望 0，得到 6）", "maxScore": 100}], "message": "全部子任务：首个错误：第 1 个测试点（n=6 m=8）第 1 行不对（期望 0，得到 6）"}	interactive-1.0.0	\N	2026-09-24 10:38:52.519+00	2026-09-24 10:38:57.229+00
