 }\\n        dag.head[u] = 0;\\n    }\\n    for (int i = 2; i <=  n; ++i)\\n    {\\n        if (!idfn[i]) continue;\\n        int t = idfn[i];\\n        if (idom[t] ^ sdom[t]) idom[t] = idom[idom[t]];\\n    }\\n    for (int i = 1; i <= n; ++i) {\\n        dep[i] = -1;\\n    }\\n    dep[s] = 0;\\n    for (int i = 2; i <= n; ++i) {\\n        if (idom[idfn[i]] == 0) continue;\\n        dep[idfn[i]] = dep[idom[idfn[i]]] + 1;\\n    }\\n    for (int i = 1; i <= n; ++i)\\n    {\\n        printf(\\"%d\\\\n\\", dep[i]);\\n    }\\n    return 0;\\n}", "language": "cpp"}	e6db94776ff0da84b76e00604402ee44	interactive	\N	completed	{"score": 60, "status": "partial", "accepted": false, "maxScore": 100}	{"tests": [{"name": "全部子任务", "time": 790, "score": 60, "memory": 48904, "status": "partial", "message": "通过 14/20 个测试点，共 60 分；首个错误：第 15 个测试点（n=200000 m=199999）第 1 行不对（期望 0，得到 (无)）", "maxScore": 100}], "message": "全部子任务：通过 14/20 个测试点，共 60 分；首个错误：第 15 个测试点（n=200000 m=199999）第 1 行不对（期望 0，得到 (无)）"}	interactive-1.0.0	\N	2026-09-24 10:39:51.044+00	2026-09-24 10:39:55.161+00
sub_01M3PWMHM3PEM68RWD3M4T4Y9M	1	sssp-hpc	kernel	{"source": "#include <vector>\\n#include <cstdint>\\n#include <queue>\\n#include <omp.h>\\n\\nvoid calculate(uint32_t n, uint32_t m, uint32_t *edges, uint64_t *dis)\\n{\\n    struct edge { uint32_t to, w; };\\n    std::vector<edge> e(m);\\n    std::vector<uint32_t> deg(n, 0);\\n    std::vector<uint32_t> offset(n);\\n    std::vector<uint32_t> pos(m);\\n\\n#pragma omp parallel for\\n    for (uint32_t i = 0; i < m; ++i) {\\n        uint32_t u = edges[i * 3];\\n        pos[i] = __atomic_fetch_add(&deg[u], 1, __ATOMIC_RELAXED);\\n    }\\n    offset[0] = 0;\\n    for (int64_t i = 1; i < n; ++i) offset[i] = offset[i - 1] + deg[i - 1];\\n#pragma omp parallel for\\n    for (int64_t i = 0; i < m; ++i) {\\n        uint32_t u = edges[i * 3], v = edges[i * 3 + 1], w = edges[i * 3 + 2];\\n        e[offset[u] + pos[i]] = (edge){v, w};\\n    }\\n\\n    std::vector<uint8_t> vis(n, 0);\\n    std::vector<uint32_t> q;\\n    q.push_back(0);\\n    while (!q.empty()) {\\n        std::vector<uint32_t> next_q;\\n        std::fill(vis.begin(), vis.end(), 0);\\n#pragma omp parallel\\n        {\\n            std::vector<uint32_t> local_next_q;\\n#pragma omp for\\n            for (uint32_t i = 0; i < q.size(); ++i) {\\n                uint32_t u = q[i];\\n                for (uint32_t j = offset[u]; j < offset[u] + deg[u]; ++j) {\\n                    uint32_t v = e[j].to;\\n                    uint64_t new_dis = dis[u] + e[j].w;\\n                    uint64_t old_dis = dis[v];\\n                    while (new_dis < old_dis) {\\n                        if (__atomic_compare_exchange_n(&dis[v], &old_dis, new_dis, false, __ATOMIC_RELAXED, __ATOMIC_RELAXED)) {\\n                            if (__atomic_exchange_n(&vis[v], 1, __ATOMIC_RELAXED) == 0) {\\n                                local_next_q.push_back(v);\\n                                break;\\n                            }\\n                        }\\n                    }\\n                }\\n            }\\n#pragma omp critical\\n            { next_q.insert(next_q.end(), local_next_q.begin(), local_next_q.end()); }\\n        }\\n        q.swap(next_q);\\n    }\\n}", "language": "cpp"}	a479a46a334ae8857520911de0e25852	interactive	\N	completed	{"score": 40, "status": "partial", "accepted": false, "maxScore": 50}	{"tests": [{"name": "1e5 点 / 2e5 边", "time": 90, "score": 10, "memory": 13692, "status": "partial", "message": "n=100000 m=200000，耗时 56.0 ms（goal 5.0 ms）", "maxScore": 20}, {"name": "1e5 点 / 1e6 边", "time": 160, "score": 20, "memory": 37728, "status": "accepted", "message": "n=100000 m=1000000，耗时 48.1 ms（goal 60.0 ms）", "maxScore": 20}, {"name": "1e6 点 / 2e6 边", "time": 940, "score": 10, "memory": 113744, "status": "accepted", "message": "n=1000000 m=2000000，耗时 109.0 ms（goal 1200.0 ms）", "maxScore": 10}], "message": "1e5 点 / 2e5 边：n=100000 m=200000，耗时 56.0 ms（goal 5.0 ms）\\n1e5 点 / 1e6 边：n=100000 m=1000000，耗时 48.1 ms（goal 60.0 ms）\\n1e6 点 / 2e6 边：n=1000000 m=2000000，耗时 109.0 ms（goal 1200.0 ms）"}	interactive-1.0.0	\N	2026-09-29 15:30:51.653+00	2026-09-29 15:30:55.342+00
