sub_01M4NZEYKB7ZY53EHS25YBTT5T	814	lu	kernel	{"source": "#include <stdio.h>\\n#include <stdlib.h>\\n#include <math.h>\\n#include <omp.h>\\n\\n#define BLOCK_SIZE 16\\n\\nvoid mydgemm(double *A,double *B,int n,int bid,int b)\\n{\\n    // 分块矩阵乘法：更新右下角子矩阵\\n    // 计算：A[right_bottom] = A[right_bottom] - A[left_block] * A[top_block]\\n    // \\n    // 优化策略：\\n    // 1. 使用分块（blocking）提高缓存命中率\\n    // 2. 使用 i-k-j 循环顺序，使内存访问更连续\\n    // 3. 小块大小选择 32，这个值可以tune一下\\n    \\n    int block_start = bid * b;          // 当前块的起始位置\\n    int block_end = block_start + b;    // 当前块的结束位置\\n    if (block_end > n) block_end = n;\\n    \\n    int right_start = block_end;        // 右下子矩阵的起始位置\\n    int matrix_size = n - right_start;  // 右下子矩阵的大小\\n    \\n    // 如果右下子矩阵很小，直接使用简单实现\\n    if (matrix_size <= BLOCK_SIZE)\\n    {\\n        // 使用 i-k-j 顺序，更缓存友好\\n        #pragma omp parallel for\\n        for (int i = right_start; i < n; i++)\\n        {\\n            size_t row_offset = (size_t)i * n;  // 优化：预计算行偏移\\n            for (int k = block_start; k < block_end; k++)\\n            {\\n                double a_ik = A[row_offset + k];\\n                size_t k_row_offset = (size_t)k * n;\\n                for (int j = right_start; j < n; j++)\\n                {\\n                    A[row_offset + j] -= a_ik * A[k_row_offset + j];\\n                }\\n            }\\n        }\\n        return;\\n    }\\n    \\n    // 对于大矩阵，使用分块算法\\n    // 分块大小：32×32\\n    int tile_size = BLOCK_SIZE;\\n    \\n    // 外层循环：遍历右下子矩阵的块（可并行）\\n    #pragma omp parallel for schedule(static)\\n    for (int ii = right_start; ii < n; ii += tile_size)\\n    {\\n        for (int jj = right_start; jj < n; jj += tile_size)\\n        {\\n            int i_end = ii + tile_size;\\n            if (i_end > n) i_end = n;\\n            \\n            int j_end = jj + tile_size;\\n            if (j_end > n) j_end = n;\\n            \\n            // 对当前块进行计算\\n            // 遍历 k 维度的所有数据\\n            for (int kk = block_start; kk < block_end; kk += tile_size)\\n            {\\n                int k_end = kk + tile_size;\\n                if (k_end > block_end) k_end = block_end;\\n                \\n                // 内层循环：在小块内使用 i-k-j 顺序\\n                for (int i = ii; i < i_end; i++)\\n                {\\n                    size_t row_offset = (size_t)i * n;  // 优化：预计算行偏移\\n                    for (int k = kk; k < k_end; k++)\\n                    {\\n                        double a_ik = A[row_offset + k];\\n                        size_t k_row_offset = (size_t)k * n;\\n                        // 向量化友好：连续访问内存\\n                        #pragma omp simd\\n                        for (int j = jj; j < j_end; j++)\\n                        {\\n                            A[row_offset + j] -= a_ik * A[k_row_offset + j];\\n                        }\\n                    }\\n                }\\n            }\\n        }\\n    }\\n}\\n\\nint mydgetrf_block(double * __restrict__ A, int * __restrict__ ipiv, int n)\\n{\\n    // 块大小：根据CPU缓存大小tune一下\\n    int b = BLOCK_SIZE;\\n    \\n    /*\\n     * 分块LU分解的核心思想：\\n     * \\n     * 标准算法每次处理1列（k从0到n-1）：\\n     *   for k = 0 to n-1:\\n     *     1. 找主元，交换行\\n     *     2. 计算L[i,k] = A[i,k]/A[k,k]（i > k）\\n     *     3. 更新子矩阵 A[i,j] -= L[i,k]*A[k,j]（i,j > k）\\n     * \\n     * 分块算法每次处理b列（一个块）：\\n     *   for block = 0 to (n/b)-1:\\n     *     1. 对对角块做标准LU分解（处理b列）同时完成对角块下侧的更新。\\n     *     2. 更新对角块右侧（相当于一次性处理b行的上三角更新）\\n     *     3. 更新右下角子矩阵（用块矩阵乘法替代逐元素更新）\\n     */\\n    \\n    // 将n×n矩阵分成多个b×b的块\\n    for (int block_id = 0; block_id * b < n; block_id++)\\n    {\\n        int block_start = block_id * b;                                    // 当前块起始行/列\\n        int block_end = block_start + b;                                   // 当前块结束行/列\\n        if (block_end > n) block_end = n;                                  // 处理最后一个不完整的块\\n        \\n        // ============================================================================\\n        // 步骤1：对当前对角块执行标准LU分解\\n        // ============================================================================\\n        // 这部分与my.c中的mydgetrf完全相同，只是范围限制在[block_start, block_end)\\n        //\\n        // 对应标准算法的：\\n        //   for k = block_start to block_end-1:\\n        //     找主元、交换、计算L、更新块内子矩阵\\n        \\n        for (int k = block_start; k < block_end; k++)\\n        {\\n            // 找主元（从第k行到最后一行）\\n            int pivot_row = k;\\n            double max_val = fabs(A[k * n + k]);            \\n            for (int i = k + 1; i < n; i++) {\\n                double val = fabs(A[i * n + k]);\\n                if (val > max_val) {\\n                    max_val = val;\\n                    pivot_row = i;\\n                }\\n            }\\n            // 奇异性检查\\n            if (max_val < 1e-14) {\\n                return 0;\\n            }\\n            // 记录置换\\n            ipiv[k] = pivot_row;\\n            // 行交换（整行交换，不只是块内）\\n            if (pivot_row != k) {\\n                size_t k_offset = (size_t)k * n;\\n                size_t pivot_offset = (size_t)pivot_row * n;\\n                for (int j = 0; j < n; j++) {\\n                    double tmp = A[k_offset + j];\\n                    A[k_offset + j] = A[pivot_offset + j];\\n                    A[pivot_offset + j] = tmp;\\n                }\\n            }\\n            \\n            // 计算L矩阵的乘数（对所有k行以下的行）\\n            double tmp = 1.0 / A[k * n + k];\\n            for (int i = k + 1,pos=i*n+k; i < n; i++,pos+=n) {\\n                A[pos] = A[pos] * tmp;\\n            }\\n            \\n            // 更新子矩阵（只更新块内的列，即 [k+1, block_end)）\\n            // 对应标准算法中：A[i,j] -= A[i,k] * A[k,j]，但j只到block_end\\n            size_t k_row_offset = (size_t)k * n;\\n            for (int i = k + 1; i < n; i++)\\n            {\\n                size_t i_row_offset = (size_t)i * n;\\n                double multiplier = A[i_row_offset + k];\\n                #pragma omp simd \\n                for (int j = k + 1; j < block_end; j++)\\n                {\\n                    A[i_row_offset + j] -= multiplier * A[k_row_offset + j];\\n                }\\n            }\\n        }\\n        \\n        // 如果还有剩余的矩阵需要更新\\n        if (block_end < n)\\n        {\\n            // ============================================================================\\n            // 步骤2：解三角方程 L11 * U12 = A12，求出U12\\n            // ============================================================================\\n            // L11是刚才得到的对角块（下三角，对角为1）\\n            // A12是对角块右侧的矩阵（block_start:block_end行，block_end:n列）\\n            // 需要用前向替换求解每一列\\n            //\\n            // 对U12的每一列j（从block_end到n）：\\n            //   对该列的每一行i（从block_start到block_end）：\\n            //     U12[i,j] = A12[i,j] - Σ(L11[i,k] * U12[k,j])，k从block_start到i-1\\n            //     因为L11[i,i]=1，不需要除法\\n            \\n            // 可以并行处理每一列\\n            #pragma omp parallel for schedule(static)\\n            for (int j = block_end; j < n; j++)  // 对右侧的每一列\\n            {\\n                for (int i = block_start; i < block_end; i++)  // 从上到下（前向替换）\\n                {\\n                    size_t i_row_offset = (size_t)i * n;\\n                    // A[i,j] -= Σ L11[i,k] * U12[k,j]，k从block_start到i-1\\n                    for (int k = block_start; k < i; k++)\\n                    {\\n                        size_t k_row_offset = (size_t)k * n;\\n                        A[i_row_offset + j] -= A[i_row_offset + k] * A[k_row_offset + j];\\n                    }\\n                    // L11[i,i]=1，所以不需要除法\\n                }\\n            }\\n            \\n            // ============================================================================\\n            // 步骤3：更新右下角子矩阵 A22 = A22 - L21 * U12\\n            // ============================================================================\\n            // 这是Schur补更新，也是分块算法的核心优化\\n            //\\n            // 此时：\\n            // - L21已经计算好了（对角块下方的列）\\n            // - U12已经计算好了（对角块右侧的行）\\n            \\n            mydgemm(A, A, n, block_id, block_end - block_start);\\n        }\\n    }\\n    \\n    return 1;\\n}\\n\\nvoid mydtrsv(char UPLO, double* __restrict__ A, double* __restrict__  B, int n, int* __restrict__ ipiv)\\n{\\n    if (UPLO == 'L' || UPLO == 'l')\\n    {\\n        // 1. Pivoting\\n        for (int i = 0; i < n; i++) {\\n            if (ipiv[i] != i) {\\n                double tmp = B[i];\\n                B[i] = B[ipiv[i]];\\n                B[ipiv[i]] = tmp;\\n            }\\n        }\\n        \\n        // 2. Forward\\n        for (int i = 0; i < n; i++) {\\n            double sum = 0.0;\\n            size_t i_offset = (size_t)i * n;\\n            \\n            // 纯串行，但强制 SIMD\\n            #pragma omp simd reduction(+:sum)\\n            for (int j = 0; j < i; j++) {\\n                sum += A[i_offset + j] * B[j];\\n            }\\n            B[i] -= sum;\\n        }\\n    }\\n    else\\n    {\\n        // 3. Backward\\n        for (int i = n - 1; i >= 0; i--) {\\n            double sum = 0.0;\\n            size_t i_offset = (size_t)i * n;\\n            \\n            #pragma omp simd reduction(+:sum)\\n            for (int j = i + 1; j < n; j++) {\\n                sum += A[i_offset + j] * B[j];\\n            }\\n            B[i] -= sum;\\n            B[i] /= A[i_offset + i];\\n        }\\n    }\\n}\\nvoid my_solver(int n, double *A, double *b)\\n{\\n    int *ipiv=(int*)malloc(n*sizeof(int));\\n    for (int i=0;i<n;i++)\\n        ipiv[i]=i;\\n    if (mydgetrf_block(A,ipiv,n)==0) \\n    {\\n        printf(\\"LU factorization failed: coefficient matrix is singular.\\\\n\\");\\n        free(ipiv);\\n        return;\\n    }\\n    mydtrsv('L',A,b,n,ipiv);\\n    mydtrsv('U',A,b,n,ipiv);\\n    free(ipiv);\\n}", "language": "cpp"}	probe-lu-1791739001329	common	\N	completed	{"score": 4, "status": "partial", "accepted": false, "maxScore": 50}	{"tests": [{"name": "N = 2049", "time": 2420, "score": 1, "memory": 112376, "status": "partial", "message": "N=2049 用时 0.398133s（满分成绩 0.1s，上限 0.5s），相对残差 8.998834e-13，15.02 GFLOPS", "maxScore": 10}, {"name": "N = 4096", "time": 2620, "score": 3, "memory": 134400, "status": "partial", "message": "N=4096 用时 1.899854s（满分成绩 0.8s，上限 3s），相对残差 7.811428e-12，24.60 GFLOPS", "maxScore": 20}, {"name": "N = 8192", "time": 2990, "score": 0, "memory": 527488, "status": "system_error", "message": "生成 N=8192 的数据失败", "maxScore": 20}], "message": "N = 2049：N=2049 用时 0.398133s（满分成绩 0.1s，上限 0.5s），相对残差 8.998834e-13，15.02 GFLOPS\\nN = 4096：N=4096 用时 1.899854s（满分成绩 0.8s，上限 3s），相对残差 7.811428e-12，24.60 GFLOPS\\nN = 8192：生成 N=8192 的数据失败"}	common-1.0.0	\N	2026-10-11 17:16:41.454+00	2026-10-11 17:16:51.032+00
sub_01M4NWQE51XFP8F2K5R07FN7PY	1	a-plus-b	kernel	{"source": "// 占位文件：评测时它会被你的提交覆盖，所以这里写什么都不影响判分。\\n//\\n// 它必须存在且非空——判题机拒绝空的 files[].content。\\n#include <iostream>\\n\\nint main() {\\n    long long a, b;\\n    std::cin >> a >> b;\\n    std::cout << a << '\\\\n';\\n    return 0;\\n}\\n", "language": "cpp"}	5b151fa5c6cfa9ecf4d61428006267e2	common	\N	completed	{"score": 25, "status": "partial", "accepted": false, "maxScore": 100}	{"tests": [{"name": "1 + 1", "time": 340, "score": 0, "memory": 65152, "status": "wrong_answer", "message": "输出 1，应为 2", "maxScore": 25}, {"name": "10^9 + 10^9", "time": 0, "score": 0, "memory": 3328, "status": "wrong_answer", "message": "输出 1000000000，应为 2000000000", "maxScore": 25}, {"name": "负数与零", "time": 0, "score": 0, "memory": 3200, "status": "wrong_answer", "message": "输出 -5，应为 -2", "maxScore": 25}, {"name": "两个零", "time": 0, "score": 25, "memory": 3072, "status": "accepted", "maxScore": 25}], "message": "1 + 1：输出 1，应为 2\\n10^9 + 10^9：输出 1000000000，应为 2000000000\\n负数与零：输出 -5，应为 -2"}	common-1.0.0	\N	2026-10-11 16:28:53.796+00	2026-10-11 16:28:54.623+00
sub_01M4NZGWQ7ZMTPD1PA80T00B4M	814	lu	kernel	{"source": "#include <stdio.h>\\n#include <stdlib.h>\\n#include <math.h>\\n#include <omp.h>\\n\\n#define BLOCK_SIZE 16\\n\\nvoid mydgemm(double *A,double *B,int n,int bid,int b)\\n{\\n    // 分块矩阵乘法：更新右下角子矩阵\\n    // 计算：A[right_bottom] = A[right_bottom] - A[left_block] * A[top_block]\\n    // \\n    // 优化策略：\\n    // 1. 使用分块（blocking）提高缓存命中率\\n    // 2. 使用 i-k-j 循环顺序，使内存访问更连续\\n    // 3. 小块大小选择 32，这个值可以tune一下\\n    \\n    int block_start = bid * b;          // 当前块的起始位置\\n    int block_end = block_start + b;    // 当前块的结束位置\\n    if (block_end > n) block_end = n;\\n    \\n    int right_start = block_end;        // 右下子矩阵的起始位置\\n    int matrix_size = n - right_start;  // 右下子矩阵的大小\\n    \\n    // 如果右下子矩阵很小，直接使用简单实现\\n    if (matrix_size <= BLOCK_SIZE)\\n    {\\n        // 使用 i-k-j 顺序，更缓存友好\\n        #pragma omp parallel for\\n        for (int i = right_start; i < n; i++)\\n        {\\n            size_t row_offset = (size_t)i * n;  // 优化：预计算行偏移\\n            for (int k = block_start; k < block_end; k++)\\n            {\\n                double a_ik = A[row_offset + k];\\n                size_t k_row_offset = (size_t)k * n;\\n                for (int j = right_start; j < n; j++)\\n                {\\n                    A[row_offset + j] -= a_ik * A[k_row_offset + j];\\n                }\\n            }\\n        }\\n        return;\\n    }\\n    \\n    // 对于大矩阵，使用分块算法\\n    // 分块大小：32×32\\n    int tile_size = BLOCK_SIZE;\\n    \\n    // 外层循环：遍历右下子矩阵的块（可并行）\\n    #pragma omp parallel for schedule(static)\\n    for (int ii = right_start; ii < n; ii += tile_size)\\n    {\\n        for (int jj = right_start; jj < n; jj += tile_size)\\n        {\\n            int i_end = ii + tile_size;\\n            if (i_end > n) i_end = n;\\n            \\n            int j_end = jj + tile_size;\\n            if (j_end > n) j_end = n;\\n            \\n            // 对当前块进行计算\\n            // 遍历 k 维度的所有数据\\n            for (int kk = block_start; kk < block_end; kk += tile_size)\\n            {\\n                int k_end = kk + tile_size;\\n                if (k_end > block_end) k_end = block_end;\\n                \\n                // 内层循环：在小块内使用 i-k-j 顺序\\n                for (int i = ii; i < i_end; i++)\\n                {\\n                    size_t row_offset = (size_t)i * n;  // 优化：预计算行偏移\\n                    for (int k = kk; k < k_end; k++)\\n                    {\\n                        double a_ik = A[row_offset + k];\\n                        size_t k_row_offset = (size_t)k * n;\\n                        // 向量化友好：连续访问内存\\n                        #pragma omp simd\\n                        for (int j = jj; j < j_end; j++)\\n                        {\\n                            A[row_offset + j] -= a_ik * A[k_row_offset + j];\\n                        }\\n                    }\\n                }\\n            }\\n        }\\n    }\\n}\\n\\nint mydgetrf_block(double * __restrict__ A, int * __restrict__ ipiv, int n)\\n{\\n    // 块大小：根据CPU缓存大小tune一下\\n    int b = BLOCK_SIZE;\\n    \\n    /*\\n     * 分块LU分解的核心思想：\\n     * \\n     * 标准算法每次处理1列（k从0到n-1）：\\n     *   for k = 0 to n-1:\\n     *     1. 找主元，交换行\\n     *     2. 计算L[i,k] = A[i,k]/A[k,k]（i > k）\\n     *     3. 更新子矩阵 A[i,j] -= L[i,k]*A[k,j]（i,j > k）\\n     * \\n     * 分块算法每次处理b列（一个块）：\\n     *   for block = 0 to (n/b)-1:\\n     *     1. 对对角块做标准LU分解（处理b列）同时完成对角块下侧的更新。\\n     *     2. 更新对角块右侧（相当于一次性处理b行的上三角更新）\\n     *     3. 更新右下角子矩阵（用块矩阵乘法替代逐元素更新）\\n     */\\n    \\n    // 将n×n矩阵分成多个b×b的块\\n    for (int block_id = 0; block_id * b < n; block_id++)\\n    {\\n        int block_start = block_id * b;                                    // 当前块起始行/列\\n        int block_end = block_start + b;                                   // 当前块结束行/列\\n        if (block_end > n) block_end = n;                                  // 处理最后一个不完整的块\\n        \\n        // ============================================================================\\n        // 步骤1：对当前对角块执行标准LU分解\\n        // ============================================================================\\n        // 这部分与my.c中的mydgetrf完全相同，只是范围限制在[block_start, block_end)\\n        //\\n        // 对应标准算法的：\\n        //   for k = block_start to block_end-1:\\n        //     找主元、交换、计算L、更新块内子矩阵\\n        \\n        for (int k = block_start; k < block_end; k++)\\n        {\\n            // 找主元（从第k行到最后一行）\\n            int pivot_row = k;\\n            double max_val = fabs(A[k * n + k]);            \\n            for (int i = k + 1; i < n; i++) {\\n                double val = fabs(A[i * n + k]);\\n                if (val > max_val) {\\n                    max_val = val;\\n                    pivot_row = i;\\n                }\\n            }\\n            // 奇异性检查\\n            if (max_val < 1e-14) {\\n                return 0;\\n            }\\n            // 记录置换\\n            ipiv[k] = pivot_row;\\n            // 行交换（整行交换，不只是块内）\\n            if (pivot_row != k) {\\n                size_t k_offset = (size_t)k * n;\\n                size_t pivot_offset = (size_t)pivot_row * n;\\n                for (int j = 0; j < n; j++) {\\n                    double tmp = A[k_offset + j];\\n                    A[k_offset + j] = A[pivot_offset + j];\\n                    A[pivot_offset + j] = tmp;\\n                }\\n            }\\n            \\n            // 计算L矩阵的乘数（对所有k行以下的行）\\n            double tmp = 1.0 / A[k * n + k];\\n            for (int i = k + 1,pos=i*n+k; i < n; i++,pos+=n) {\\n                A[pos] = A[pos] * tmp;\\n            }\\n            \\n            // 更新子矩阵（只更新块内的列，即 [k+1, block_end)）\\n            // 对应标准算法中：A[i,j] -= A[i,k] * A[k,j]，但j只到block_end\\n            size_t k_row_offset = (size_t)k * n;\\n            for (int i = k + 1; i < n; i++)\\n            {\\n                size_t i_row_offset = (size_t)i * n;\\n                double multiplier = A[i_row_offset + k];\\n                #pragma omp simd \\n                for (int j = k + 1; j < block_end; j++)\\n                {\\n                    A[i_row_offset + j] -= multiplier * A[k_row_offset + j];\\n                }\\n            }\\n        }\\n        \\n        // 如果还有剩余的矩阵需要更新\\n        if (block_end < n)\\n        {\\n            // ============================================================================\\n            // 步骤2：解三角方程 L11 * U12 = A12，求出U12\\n            // ============================================================================\\n            // L11是刚才得到的对角块（下三角，对角为1）\\n            // A12是对角块右侧的矩阵（block_start:block_end行，block_end:n列）\\n            // 需要用前向替换求解每一列\\n            //\\n            // 对U12的每一列j（从block_end到n）：\\n            //   对该列的每一行i（从block_start到block_end）：\\n            //     U12[i,j] = A12[i,j] - Σ(L11[i,k] * U12[k,j])，k从block_start到i-1\\n            //     因为L11[i,i]=1，不需要除法\\n            \\n            // 可以并行处理每一列\\n            #pragma omp parallel for schedule(static)\\n            for (int j = block_end; j < n; j++)  // 对右侧的每一列\\n            {\\n                for (int i = block_start; i < block_end; i++)  // 从上到下（前向替换）\\n                {\\n                    size_t i_row_offset = (size_t)i * n;\\n                    // A[i,j] -= Σ L11[i,k] * U12[k,j]，k从block_start到i-1\\n                    for (int k = block_start; k < i; k++)\\n                    {\\n                        size_t k_row_offset = (size_t)k * n;\\n                        A[i_row_offset + j] -= A[i_row_offset + k] * A[k_row_offset + j];\\n                    }\\n                    // L11[i,i]=1，所以不需要除法\\n                }\\n            }\\n            \\n            // ============================================================================\\n            // 步骤3：更新右下角子矩阵 A22 = A22 - L21 * U12\\n            // ============================================================================\\n            // 这是Schur补更新，也是分块算法的核心优化\\n            //\\n            // 此时：\\n            // - L21已经计算好了（对角块下方的列）\\n            // - U12已经计算好了（对角块右侧的行）\\n            \\n            mydgemm(A, A, n, block_id, block_end - block_start);\\n        }\\n    }\\n    \\n    return 1;\\n}\\n\\nvoid mydtrsv(char UPLO, double* __restrict__ A, double* __restrict__  B, int n, int* __restrict__ ipiv)\\n{\\n    if (UPLO == 'L' || UPLO == 'l')\\n    {\\n        // 1. Pivoting\\n        for (int i = 0; i < n; i++) {\\n            if (ipiv[i] != i) {\\n                double tmp = B[i];\\n                B[i] = B[ipiv[i]];\\n                B[ipiv[i]] = tmp;\\n            }\\n        }\\n        \\n        // 2. Forward\\n        for (int i = 0; i < n; i++) {\\n            double sum = 0.0;\\n            size_t i_offset = (size_t)i * n;\\n            \\n            // 纯串行，但强制 SIMD\\n            #pragma omp simd reduction(+:sum)\\n            for (int j = 0; j < i; j++) {\\n                sum += A[i_offset + j] * B[j];\\n            }\\n            B[i] -= sum;\\n        }\\n    }\\n    else\\n    {\\n        // 3. Backward\\n        for (int i = n - 1; i >= 0; i--) {\\n            double sum = 0.0;\\n            size_t i_offset = (size_t)i * n;\\n            \\n            #pragma omp simd reduction(+:sum)\\n            for (int j = i + 1; j < n; j++) {\\n                sum += A[i_offset + j] * B[j];\\n            }\\n            B[i] -= sum;\\n            B[i] /= A[i_offset + i];\\n        }\\n    }\\n}\\nvoid my_solver(int n, double *A, double *b)\\n{\\n    int *ipiv=(int*)malloc(n*sizeof(int));\\n    for (int i=0;i<n;i++)\\n        ipiv[i]=i;\\n    if (mydgetrf_block(A,ipiv,n)==0) \\n    {\\n        printf(\\"LU factorization failed: coefficient matrix is singular.\\\\n\\");\\n        free(ipiv);\\n        return;\\n    }\\n    mydtrsv('L',A,b,n,ipiv);\\n    mydtrsv('U',A,b,n,ipiv);\\n    free(ipiv);\\n}", "language": "cpp"}	probe-lu-1791739065017	common	\N	completed	{"score": 4, "status": "partial", "accepted": false, "maxScore": 50}	{"tests": [{"name": "N = 2049", "time": 1880, "score": 1, "memory": 112596, "status": "partial", "message": "N=2049 用时 0.369457s（满分成绩 0.1s，上限 0.5s），相对残差 7.044714e-13，16.07 GFLOPS", "maxScore": 10}, {"name": "N = 4096", "time": 2590, "score": 3, "memory": 134528, "status": "partial", "message": "N=4096 用时 1.883265s（满分成绩 0.8s，上限 3s），相对残差 4.703202e-12，24.80 GFLOPS", "maxScore": 20}, {"name": "N = 8192", "time": 14400, "score": 0, "memory": 527616, "status": "time_limit_exceeded", "message": "N=8192 用时 11.804731s，超过 10s 的限制", "maxScore": 20}], "message": "N = 2049：N=2049 用时 0.369457s（满分成绩 0.1s，上限 0.5s），相对残差 7.044714e-13，16.07 GFLOPS\\nN = 4096：N=4096 用时 1.883265s（满分成绩 0.8s，上限 3s），相对残差 4.703202e-12，24.80 GFLOPS\\nN = 8192：N=8192 用时 11.804731s，超过 10s 的限制"}	common-1.0.0	\N	2026-10-11 17:17:45.065+00	2026-10-11 17:18:04.414+00
sub_01M4P01MPY79YA72SMCC447J49	1	lu	kernel	{"source": "// The contestant file: implement my_solver here, and do NOT write main --\\n// driver.cpp already owns it. The judge overwrites this file with payload.source.\\n//\\n// What ships here is the naive implementation from the statement (single\\n// threaded, no blocking). It keeps the problem compilable out of the box and is\\n// the starting point for local testing. It is correct but slow: at N=2049 it\\n// already exceeds the 0.5 s limit, so submitting it unchanged scores 0 -- which\\n// is the whole point of scoring against the per-test full-mark time.\\n#include <cstdio>\\n#include <cstdlib>\\n#include <cmath>\\n\\nint mydgetrf(double *A,int *ipiv,int n)\\n{\\n    // LU decomposition with partial pivoting\\n    // A is stored in row-major format\\n    // On exit, A contains L (below diagonal with unit diagonal) and U (on and above diagonal)\\n    \\n    for (int k = 0; k < n; k++)\\n    {\\n        // Find pivot (max element in column k from row k to n-1)\\n        int pivot_row = k;\\n        double max_val = fabs(A[k * n + k]);\\n        \\n        for (int i = k + 1; i < n; i++)\\n        {\\n            double val = fabs(A[i * n + k]);\\n            if (val > max_val)\\n            {\\n                max_val = val;\\n                pivot_row = i;\\n            }\\n        }\\n        \\n        // Check for singularity\\n        if (max_val < 1e-14)\\n        {\\n            return 0; // Matrix is singular\\n        }\\n        \\n        // Record pivot\\n        ipiv[k] = pivot_row;\\n        \\n        // Swap rows k and pivot_row if needed\\n        if (pivot_row != k)\\n        {\\n            for (int j = 0; j < n; j++)\\n            {\\n                double tmp = A[k * n + j];\\n                A[k * n + j] = A[pivot_row * n + j];\\n                A[pivot_row * n + j] = tmp;\\n            }\\n        }\\n        \\n        // Compute multipliers and update submatrix\\n        for (int i = k + 1; i < n; i++)\\n        {\\n            // Compute multiplier L[i,k]\\n            A[i * n + k] = A[i * n + k] / A[k * n + k];\\n            \\n            // Update row i: A[i,k+1:n] -= L[i,k] * A[k,k+1:n]\\n            for (int j = k + 1; j < n; j++)\\n            {\\n                A[i * n + j] -= A[i * n + k] * A[k * n + j];\\n            }\\n        }\\n    }\\n    \\n    return 1;\\n}\\n\\nvoid mydtrsv(char UPLO,double *A,double *B,int n,int *ipiv)\\n{\\n    // Solve triangular system\\n    // A is in row-major format\\n    // UPLO='L': solve Lx=B (L has unit diagonal)\\n    // UPLO='U': solve Ux=B (U has non-unit diagonal)\\n    \\n    if (UPLO == 'L' || UPLO == 'l')\\n    {\\n        // Forward substitution for lower triangular system with unit diagonal\\n        // Apply pivoting first\\n        for (int i = 0; i < n; i++)\\n        {\\n            if (ipiv[i] != i)\\n            {\\n                double tmp = B[i];\\n                B[i] = B[ipiv[i]];\\n                B[ipiv[i]] = tmp;\\n            }\\n        }\\n        \\n        // Solve Lx=B where L has unit diagonal\\n        for (int i = 0; i < n; i++)\\n        {\\n            for (int j = 0; j < i; j++)\\n            {\\n                B[i] -= A[i * n + j] * B[j];\\n            }\\n            // Note: L[i,i] = 1, so no division needed\\n        }\\n    }\\n    else if (UPLO == 'U' || UPLO == 'u')\\n    {\\n        // Backward substitution for upper triangular system\\n        // Solve Ux=B\\n        for (int i = n - 1; i >= 0; i--)\\n        {\\n            for (int j = i + 1; j < n; j++)\\n            {\\n                B[i] -= A[i * n + j] * B[j];\\n            }\\n            B[i] /= A[i * n + i];\\n        }\\n    }\\n}\\n\\nvoid my_solver(int n, double *A, double *b)\\n{\\n    int *ipiv=(int*)malloc(n*sizeof(int));\\n    for (int i=0;i<n;i++)\\n        ipiv[i]=i;\\n    if (mydgetrf(A,ipiv,n)==0) \\n    {\\n        printf(\\"LU factorization failed: coefficient matrix is singular.\\\\n\\");\\n        free(ipiv);\\n        return;\\n    }\\n    mydtrsv('L',A,b,n,ipiv);\\n    mydtrsv('U',A,b,n,ipiv);\\n    free(ipiv);\\n}\\n", "language": "cpp"}	2712331794f77f9a406d047ed370f8ca	common	\N	completed	{"score": 0, "status": "time_limit_exceeded", "accepted": false, "maxScore": 50}	{"tests": [{"name": "N = 2049", "time": 2280, "score": 0, "memory": 112544, "status": "time_limit_exceeded", "message": "N=2049 用时 0.890017s，超过 0.5s 的限制", "maxScore": 10}, {"name": "N = 4096", "time": 9501, "score": 0, "memory": 0, "status": "time_limit_exceeded", "maxScore": 20}, {"name": "N = 8192", "time": 16502, "score": 0, "memory": 0, "status": "time_limit_exceeded", "maxScore": 20}], "message": "N = 2049：N=2049 用时 0.890017s，超过 0.5s 的限制"}	common-1.0.0	\N	2026-10-11 17:26:53.922+00	2026-10-11 17:27:23.435+00
sub_01M4P03ZRSWN28MYJATMCYSXXJ	1	lu	kernel	{"source": "#include <stdio.h>\\n#include <stdlib.h>\\n#include <math.h>\\n#include <omp.h>\\n\\n#define BLOCK_SIZE 16\\n\\nvoid mydgemm(double *A,double *B,int n,int bid,int b)\\n{\\n    // 分块矩阵乘法：更新右下角子矩阵\\n    // 计算：A[right_bottom] = A[right_bottom] - A[left_block] * A[top_block]\\n    // \\n    // 优化策略：\\n    // 1. 使用分块（blocking）提高缓存命中率\\n    // 2. 使用 i-k-j 循环顺序，使内存访问更连续\\n    // 3. 小块大小选择 32，这个值可以tune一下\\n    \\n    int block_start = bid * b;          // 当前块的起始位置\\n    int block_end = block_start + b;    // 当前块的结束位置\\n    if (block_end > n) block_end = n;\\n    \\n    int right_start = block_end;        // 右下子矩阵的起始位置\\n    int matrix_size = n - right_start;  // 右下子矩阵的大小\\n    \\n    // 如果右下子矩阵很小，直接使用简单实现\\n    if (matrix_size <= BLOCK_SIZE)\\n    {\\n        // 使用 i-k-j 顺序，更缓存友好\\n        #pragma omp parallel for\\n        for (int i = right_start; i < n; i++)\\n        {\\n            size_t row_offset = (size_t)i * n;  // 优化：预计算行偏移\\n            for (int k = block_start; k < block_end; k++)\\n            {\\n                double a_ik = A[row_offset + k];\\n                size_t k_row_offset = (size_t)k * n;\\n                for (int j = right_start; j < n; j++)\\n                {\\n                    A[row_offset + j] -= a_ik * A[k_row_offset + j];\\n                }\\n            }\\n        }\\n        return;\\n    }\\n    \\n    // 对于大矩阵，使用分块算法\\n    // 分块大小：32×32\\n    int tile_size = BLOCK_SIZE;\\n    \\n    // 外层循环：遍历右下子矩阵的块（可并行）\\n    #pragma omp parallel for schedule(static)\\n    for (int ii = right_start; ii < n; ii += tile_size)\\n    {\\n        for (int jj = right_start; jj < n; jj += tile_size)\\n        {\\n            int i_end = ii + tile_size;\\n            if (i_end > n) i_end = n;\\n            \\n            int j_end = jj + tile_size;\\n            if (j_end > n) j_end = n;\\n            \\n            // 对当前块进行计算\\n            // 遍历 k 维度的所有数据\\n            for (int kk = block_start; kk < block_end; kk += tile_size)\\n            {\\n                int k_end = kk + tile_size;\\n                if (k_end > block_end) k_end = block_end;\\n                \\n                // 内层循环：在小块内使用 i-k-j 顺序\\n                for (int i = ii; i < i_end; i++)\\n                {\\n                    size_t row_offset = (size_t)i * n;  // 优化：预计算行偏移\\n                    for (int k = kk; k < k_end; k++)\\n                    {\\n                        double a_ik = A[row_offset + k];\\n                        size_t k_row_offset = (size_t)k * n;\\n                        // 向量化友好：连续访问内存\\n                        #pragma omp simd\\n                        for (int j = jj; j < j_end; j++)\\n                        {\\n                            A[row_offset + j] -= a_ik * A[k_row_offset + j];\\n                        }\\n                    }\\n                }\\n            }\\n        }\\n    }\\n}\\n\\nint mydgetrf_block(double * __restrict__ A, int * __restrict__ ipiv, int n)\\n{\\n    // 块大小：根据CPU缓存大小tune一下\\n    int b = BLOCK_SIZE;\\n    \\n    /*\\n     * 分块LU分解的核心思想：\\n     * \\n     * 标准算法每次处理1列（k从0到n-1）：\\n     *   for k = 0 to n-1:\\n     *     1. 找主元，交换行\\n     *     2. 计算L[i,k] = A[i,k]/A[k,k]（i > k）\\n     *     3. 更新子矩阵 A[i,j] -= L[i,k]*A[k,j]（i,j > k）\\n     * \\n     * 分块算法每次处理b列（一个块）：\\n     *   for block = 0 to (n/b)-1:\\n     *     1. 对对角块做标准LU分解（处理b列）同时完成对角块下侧的更新。\\n     *     2. 更新对角块右侧（相当于一次性处理b行的上三角更新）\\n     *     3. 更新右下角子矩阵（用块矩阵乘法替代逐元素更新）\\n     */\\n    \\n    // 将n×n矩阵分成多个b×b的块\\n    for (int block_id = 0; block_id * b < n; block_id++)\\n    {\\n        int block_start = block_id * b;                                    // 当前块起始行/列\\n        int block_end = block_start + b;                                   // 当前块结束行/列\\n        if (block_end > n) block_end = n;                                  // 处理最后一个不完整的块\\n        \\n        // ============================================================================\\n        // 步骤1：对当前对角块执行标准LU分解\\n        // ============================================================================\\n        // 这部分与my.c中的mydgetrf完全相同，只是范围限制在[block_start, block_end)\\n        //\\n        // 对应标准算法的：\\n        //   for k = block_start to block_end-1:\\n        //     找主元、交换、计算L、更新块内子矩阵\\n        \\n        for (int k = block_start; k < block_end; k++)\\n        {\\n            // 找主元（从第k行到最后一行）\\n            int pivot_row = k;\\n            double max_val = fabs(A[k * n + k]);            \\n            for (int i = k + 1; i < n; i++) {\\n                double val = fabs(A[i * n + k]);\\n                if (val > max_val) {\\n                    max_val = val;\\n                    pivot_row = i;\\n                }\\n            }\\n            // 奇异性检查\\n            if (max_val < 1e-14) {\\n                return 0;\\n            }\\n            // 记录置换\\n            ipiv[k] = pivot_row;\\n            // 行交换（整行交换，不只是块内）\\n            if (pivot_row != k) {\\n                size_t k_offset = (size_t)k * n;\\n                size_t pivot_offset = (size_t)pivot_row * n;\\n                for (int j = 0; j < n; j++) {\\n                    double tmp = A[k_offset + j];\\n                    A[k_offset + j] = A[pivot_offset + j];\\n                    A[pivot_offset + j] = tmp;\\n                }\\n            }\\n            \\n            // 计算L矩阵的乘数（对所有k行以下的行）\\n            double tmp = 1.0 / A[k * n + k];\\n            for (int i = k + 1,pos=i*n+k; i < n; i++,pos+=n) {\\n                A[pos] = A[pos] * tmp;\\n            }\\n            \\n            // 更新子矩阵（只更新块内的列，即 [k+1, block_end)）\\n            // 对应标准算法中：A[i,j] -= A[i,k] * A[k,j]，但j只到block_end\\n            size_t k_row_offset = (size_t)k * n;\\n            for (int i = k + 1; i < n; i++)\\n            {\\n                size_t i_row_offset = (size_t)i * n;\\n                double multiplier = A[i_row_offset + k];\\n                #pragma omp simd \\n                for (int j = k + 1; j < block_end; j++)\\n                {\\n                    A[i_row_offset + j] -= multiplier * A[k_row_offset + j];\\n                }\\n            }\\n        }\\n        \\n        // 如果还有剩余的矩阵需要更新\\n        if (block_end < n)\\n        {\\n            // ============================================================================\\n            // 步骤2：解三角方程 L11 * U12 = A12，求出U12\\n            // ============================================================================\\n            // L11是刚才得到的对角块（下三角，对角为1）\\n            // A12是对角块右侧的矩阵（block_start:block_end行，block_end:n列）\\n            // 需要用前向替换求解每一列\\n            //\\n            // 对U12的每一列j（从block_end到n）：\\n            //   对该列的每一行i（从block_start到block_end）：\\n            //     U12[i,j] = A12[i,j] - Σ(L11[i,k] * U12[k,j])，k从block_start到i-1\\n            //     因为L11[i,i]=1，不需要除法\\n            \\n            // 可以并行处理每一列\\n            #pragma omp parallel for schedule(static)\\n            for (int j = block_end; j < n; j++)  // 对右侧的每一列\\n            {\\n                for (int i = block_start; i < block_end; i++)  // 从上到下（前向替换）\\n                {\\n                    size_t i_row_offset = (size_t)i * n;\\n                    // A[i,j] -= Σ L11[i,k] * U12[k,j]，k从block_start到i-1\\n                    for (int k = block_start; k < i; k++)\\n                    {\\n                        size_t k_row_offset = (size_t)k * n;\\n                        A[i_row_offset + j] -= A[i_row_offset + k] * A[k_row_offset + j];\\n                    }\\n                    // L11[i,i]=1，所以不需要除法\\n                }\\n            }\\n            \\n            // ============================================================================\\n            // 步骤3：更新右下角子矩阵 A22 = A22 - L21 * U12\\n            // ============================================================================\\n            // 这是Schur补更新，也是分块算法的核心优化\\n            //\\n            // 此时：\\n            // - L21已经计算好了（对角块下方的列）\\n            // - U12已经计算好了（对角块右侧的行）\\n            \\n            mydgemm(A, A, n, block_id, block_end - block_start);\\n        }\\n    }\\n    \\n    return 1;\\n}\\n\\nvoid mydtrsv(char UPLO, double* __restrict__ A, double* __restrict__  B, int n, int* __restrict__ ipiv)\\n{\\n    if (UPLO == 'L' || UPLO == 'l')\\n    {\\n        // 1. Pivoting\\n        for (int i = 0; i < n; i++) {\\n            if (ipiv[i] != i) {\\n                double tmp = B[i];\\n                B[i] = B[ipiv[i]];\\n                B[ipiv[i]] = tmp;\\n            }\\n        }\\n        \\n        // 2. Forward\\n        for (int i = 0; i < n; i++) {\\n            double sum = 0.0;\\n            size_t i_offset = (size_t)i * n;\\n            \\n            // 纯串行，但强制 SIMD\\n            #pragma omp simd reduction(+:sum)\\n            for (int j = 0; j < i; j++) {\\n                sum += A[i_offset + j] * B[j];\\n            }\\n            B[i] -= sum;\\n        }\\n    }\\n    else\\n    {\\n        // 3. Backward\\n        for (int i = n - 1; i >= 0; i--) {\\n            double sum = 0.0;\\n            size_t i_offset = (size_t)i * n;\\n            \\n            #pragma omp simd reduction(+:sum)\\n            for (int j = i + 1; j < n; j++) {\\n                sum += A[i_offset + j] * B[j];\\n            }\\n            B[i] -= sum;\\n            B[i] /= A[i_offset + i];\\n        }\\n    }\\n}\\nvoid my_solver(int n, double *A, double *b)\\n{\\n    int *ipiv=(int*)malloc(n*sizeof(int));\\n    for (int i=0;i<n;i++)\\n        ipiv[i]=i;\\n    if (mydgetrf_block(A,ipiv,n)==0) \\n    {\\n        printf(\\"LU factorization failed: coefficient matrix is singular.\\\\n\\");\\n        free(ipiv);\\n        return;\\n    }\\n    mydtrsv('L',A,b,n,ipiv);\\n    mydtrsv('U',A,b,n,ipiv);\\n    free(ipiv);\\n}", "language": "cpp"}	11f2ff2892d5b3dceaf66eb2e4d4530d	common	\N	completed	{"score": 4, "status": "partial", "accepted": false, "maxScore": 50}	{"tests": [{"name": "N = 2049", "time": 1900, "score": 1, "memory": 112388, "status": "partial", "message": "N=2049 用时 0.395888s（满分成绩 0.1s，上限 0.5s），相对残差 7.320457e-12，15.00 GFLOPS", "maxScore": 10}, {"name": "N = 4096", "time": 2680, "score": 3, "memory": 134400, "status": "partial", "message": "N=4096 用时 1.964698s（满分成绩 0.8s，上限 3s），相对残差 6.239893e-12，23.79 GFLOPS", "maxScore": 20}, {"name": "N = 8192", "time": 14570, "score": 0, "memory": 527616, "status": "time_limit_exceeded", "message": "N=8192 用时 11.668248s，超过 10s 的限制", "maxScore": 20}], "message": "N = 2049：N=2049 用时 0.395888s（满分成绩 0.1s，上限 0.5s），相对残差 7.320457e-12，15.00 GFLOPS\\nN = 4096：N=4096 用时 1.964698s（满分成绩 0.8s，上限 3s），相对残差 6.239893e-12，23.79 GFLOPS\\nN = 8192：N=8192 用时 11.668248s，超过 10s 的限制"}	common-1.0.0	\N	2026-10-11 17:28:10.78+00	2026-10-11 17:28:30.315+00
sub_01M4P0FK5EF4AN4SWN2JH984NP	814	lu	kernel	{"source": "#include <stdio.h>\\n#include <stdlib.h>\\n#include <math.h>\\n#include <omp.h>\\n\\n#define BLOCK_SIZE 16\\n\\nvoid mydgemm(double *A,double *B,int n,int bid,int b)\\n{\\n    // 分块矩阵乘法：更新右下角子矩阵\\n    // 计算：A[right_bottom] = A[right_bottom] - A[left_block] * A[top_block]\\n    // \\n    // 优化策略：\\n    // 1. 使用分块（blocking）提高缓存命中率\\n    // 2. 使用 i-k-j 循环顺序，使内存访问更连续\\n    // 3. 小块大小选择 32，这个值可以tune一下\\n    \\n    int block_start = bid * b;          // 当前块的起始位置\\n    int block_end = block_start + b;    // 当前块的结束位置\\n    if (block_end > n) block_end = n;\\n    \\n    int right_start = block_end;        // 右下子矩阵的起始位置\\n    int matrix_size = n - right_start;  // 右下子矩阵的大小\\n    \\n    // 如果右下子矩阵很小，直接使用简单实现\\n    if (matrix_size <= BLOCK_SIZE)\\n    {\\n        // 使用 i-k-j 顺序，更缓存友好\\n        #pragma omp parallel for\\n        for (int i = right_start; i < n; i++)\\n        {\\n            size_t row_offset = (size_t)i * n;  // 优化：预计算行偏移\\n            for (int k = block_start; k < block_end; k++)\\n            {\\n                double a_ik = A[row_offset + k];\\n                size_t k_row_offset = (size_t)k * n;\\n                for (int j = right_start; j < n; j++)\\n                {\\n                    A[row_offset + j] -= a_ik * A[k_row_offset + j];\\n                }\\n            }\\n        }\\n        return;\\n    }\\n    \\n    // 对于大矩阵，使用分块算法\\n    // 分块大小：32×32\\n    int tile_size = BLOCK_SIZE;\\n    \\n    // 外层循环：遍历右下子矩阵的块（可并行）\\n    #pragma omp parallel for schedule(static)\\n    for (int ii = right_start; ii < n; ii += tile_size)\\n    {\\n        for (int jj = right_start; jj < n; jj += tile_size)\\n        {\\n            int i_end = ii + tile_size;\\n            if (i_end > n) i_end = n;\\n            \\n            int j_end = jj + tile_size;\\n            if (j_end > n) j_end = n;\\n            \\n            // 对当前块进行计算\\n            // 遍历 k 维度的所有数据\\n            for (int kk = block_start; kk < block_end; kk += tile_size)\\n            {\\n                int k_end = kk + tile_size;\\n                if (k_end > block_end) k_end = block_end;\\n                \\n                // 内层循环：在小块内使用 i-k-j 顺序\\n                for (int i = ii; i < i_end; i++)\\n                {\\n                    size_t row_offset = (size_t)i * n;  // 优化：预计算行偏移\\n                    for (int k = kk; k < k_end; k++)\\n                    {\\n                        double a_ik = A[row_offset + k];\\n                        size_t k_row_offset = (size_t)k * n;\\n                        // 向量化友好：连续访问内存\\n                        #pragma omp simd\\n                        for (int j = jj; j < j_end; j++)\\n                        {\\n                            A[row_offset + j] -= a_ik * A[k_row_offset + j];\\n                        }\\n                    }\\n                }\\n            }\\n        }\\n    }\\n}\\n\\nint mydgetrf_block(double * __restrict__ A, int * __restrict__ ipiv, int n)\\n{\\n    // 块大小：根据CPU缓存大小tune一下\\n    int b = BLOCK_SIZE;\\n    \\n    /*\\n     * 分块LU分解的核心思想：\\n     * \\n     * 标准算法每次处理1列（k从0到n-1）：\\n     *   for k = 0 to n-1:\\n     *     1. 找主元，交换行\\n     *     2. 计算L[i,k] = A[i,k]/A[k,k]（i > k）\\n     *     3. 更新子矩阵 A[i,j] -= L[i,k]*A[k,j]（i,j > k）\\n     * \\n     * 分块算法每次处理b列（一个块）：\\n     *   for block = 0 to (n/b)-1:\\n     *     1. 对对角块做标准LU分解（处理b列）同时完成对角块下侧的更新。\\n     *     2. 更新对角块右侧（相当于一次性处理b行的上三角更新）\\n     *     3. 更新右下角子矩阵（用块矩阵乘法替代逐元素更新）\\n     */\\n    \\n    // 将n×n矩阵分成多个b×b的块\\n    for (int block_id = 0; block_id * b < n; block_id++)\\n    {\\n        int block_start = block_id * b;                                    // 当前块起始行/列\\n        int block_end = block_start + b;                                   // 当前块结束行/列\\n        if (block_end > n) block_end = n;                                  // 处理最后一个不完整的块\\n        \\n        // ============================================================================\\n        // 步骤1：对当前对角块执行标准LU分解\\n        // ============================================================================\\n        // 这部分与my.c中的mydgetrf完全相同，只是范围限制在[block_start, block_end)\\n        //\\n        // 对应标准算法的：\\n        //   for k = block_start to block_end-1:\\n        //     找主元、交换、计算L、更新块内子矩阵\\n        \\n        for (int k = block_start; k < block_end; k++)\\n        {\\n            // 找主元（从第k行到最后一行）\\n            int pivot_row = k;\\n            double max_val = fabs(A[k * n + k]);            \\n            for (int i = k + 1; i < n; i++) {\\n                double val = fabs(A[i * n + k]);\\n                if (val > max_val) {\\n                    max_val = val;\\n                    pivot_row = i;\\n                }\\n            }\\n            // 奇异性检查\\n            if (max_val < 1e-14) {\\n                return 0;\\n            }\\n            // 记录置换\\n            ipiv[k] = pivot_row;\\n            // 行交换（整行交换，不只是块内）\\n            if (pivot_row != k) {\\n                size_t k_offset = (size_t)k * n;\\n                size_t pivot_offset = (size_t)pivot_row * n;\\n                for (int j = 0; j < n; j++) {\\n                    double tmp = A[k_offset + j];\\n                    A[k_offset + j] = A[pivot_offset + j];\\n                    A[pivot_offset + j] = tmp;\\n                }\\n            }\\n            \\n            // 计算L矩阵的乘数（对所有k行以下的行）\\n            double tmp = 1.0 / A[k * n + k];\\n            for (int i = k + 1,pos=i*n+k; i < n; i++,pos+=n) {\\n                A[pos] = A[pos] * tmp;\\n            }\\n            \\n            // 更新子矩阵（只更新块内的列，即 [k+1, block_end)）\\n            // 对应标准算法中：A[i,j] -= A[i,k] * A[k,j]，但j只到block_end\\n            size_t k_row_offset = (size_t)k * n;\\n            for (int i = k + 1; i < n; i++)\\n            {\\n                size_t i_row_offset = (size_t)i * n;\\n                double multiplier = A[i_row_offset + k];\\n                #pragma omp simd \\n                for (int j = k + 1; j < block_end; j++)\\n                {\\n                    A[i_row_offset + j] -= multiplier * A[k_row_offset + j];\\n                }\\n            }\\n        }\\n        \\n        // 如果还有剩余的矩阵需要更新\\n        if (block_end < n)\\n        {\\n            // ============================================================================\\n            // 步骤2：解三角方程 L11 * U12 = A12，求出U12\\n            // ============================================================================\\n            // L11是刚才得到的对角块（下三角，对角为1）\\n            // A12是对角块右侧的矩阵（block_start:block_end行，block_end:n列）\\n            // 需要用前向替换求解每一列\\n            //\\n            // 对U12的每一列j（从block_end到n）：\\n            //   对该列的每一行i（从block_start到block_end）：\\n            //     U12[i,j] = A12[i,j] - Σ(L11[i,k] * U12[k,j])，k从block_start到i-1\\n            //     因为L11[i,i]=1，不需要除法\\n            \\n            // 可以并行处理每一列\\n            #pragma omp parallel for schedule(static)\\n            for (int j = block_end; j < n; j++)  // 对右侧的每一列\\n            {\\n                for (int i = block_start; i < block_end; i++)  // 从上到下（前向替换）\\n                {\\n                    size_t i_row_offset = (size_t)i * n;\\n                    // A[i,j] -= Σ L11[i,k] * U12[k,j]，k从block_start到i-1\\n                    for (int k = block_start; k < i; k++)\\n                    {\\n                        size_t k_row_offset = (size_t)k * n;\\n                        A[i_row_offset + j] -= A[i_row_offset + k] * A[k_row_offset + j];\\n                    }\\n                    // L11[i,i]=1，所以不需要除法\\n                }\\n            }\\n            \\n            // ============================================================================\\n            // 步骤3：更新右下角子矩阵 A22 = A22 - L21 * U12\\n            // ============================================================================\\n            // 这是Schur补更新，也是分块算法的核心优化\\n            //\\n            // 此时：\\n            // - L21已经计算好了（对角块下方的列）\\n            // - U12已经计算好了（对角块右侧的行）\\n            \\n            mydgemm(A, A, n, block_id, block_end - block_start);\\n        }\\n    }\\n    \\n    return 1;\\n}\\n\\nvoid mydtrsv(char UPLO, double* __restrict__ A, double* __restrict__  B, int n, int* __restrict__ ipiv)\\n{\\n    if (UPLO == 'L' || UPLO == 'l')\\n    {\\n        // 1. Pivoting\\n        for (int i = 0; i < n; i++) {\\n            if (ipiv[i] != i) {\\n                double tmp = B[i];\\n                B[i] = B[ipiv[i]];\\n                B[ipiv[i]] = tmp;\\n            }\\n        }\\n        \\n        // 2. Forward\\n        for (int i = 0; i < n; i++) {\\n            double sum = 0.0;\\n            size_t i_offset = (size_t)i * n;\\n            \\n            // 纯串行，但强制 SIMD\\n            #pragma omp simd reduction(+:sum)\\n            for (int j = 0; j < i; j++) {\\n                sum += A[i_offset + j] * B[j];\\n            }\\n            B[i] -= sum;\\n        }\\n    }\\n    else\\n    {\\n        // 3. Backward\\n        for (int i = n - 1; i >= 0; i--) {\\n            double sum = 0.0;\\n            size_t i_offset = (size_t)i * n;\\n            \\n            #pragma omp simd reduction(+:sum)\\n            for (int j = i + 1; j < n; j++) {\\n                sum += A[i_offset + j] * B[j];\\n            }\\n            B[i] -= sum;\\n            B[i] /= A[i_offset + i];\\n        }\\n    }\\n}\\nvoid my_solver(int n, double *A, double *b)\\n{\\n    int *ipiv=(int*)malloc(n*sizeof(int));\\n    for (int i=0;i<n;i++)\\n        ipiv[i]=i;\\n    if (mydgetrf_block(A,ipiv,n)==0) \\n    {\\n        printf(\\"LU factorization failed: coefficient matrix is singular.\\\\n\\");\\n        free(ipiv);\\n        return;\\n    }\\n    mydtrsv('L',A,b,n,ipiv);\\n    mydtrsv('U',A,b,n,ipiv);\\n    free(ipiv);\\n}", "language": "cpp"}	probe-lu-1791740070975	common	\N	completed	{"score": 50, "status": "accepted", "accepted": true, "maxScore": 50}	{"tests": [{"name": "N = 2049", "time": 1600, "score": 10, "memory": 112228, "status": "a