sub_01M4P05990BEF4QA8HP0ZCYBMJ	1	lu	kernel	{"source": "#include <stdio.h>\\n#include <stdlib.h>\\n#include <math.h>\\n#include <omp.h>\\n#include <cblas.h>\\n\\nvoid my_solver(int n, double *A, double *b)\\n{\\n    int *ipiv = (int*)malloc(n * sizeof(int));\\n    int info;\\n    \\n    dgetrf_(&n, &n, A, &n, ipiv, &info);\\n    \\n    if (info != 0) {\\n        printf(\\"LU factorization failed (info=%d).\\\\n\\", info);\\n        free(ipiv);\\n        return;\\n    }\\n    \\n    char trans = 'T';  // 解 (A^T)^T x = Ax = b\\n    int nrhs = 1;\\n    dgetrs_(&trans, &n, &nrhs, A, &n, ipiv, b, &n, &info);\\n    \\n    if (info != 0) {\\n        printf(\\"Solution failed (info=%d).\\\\n\\", info);\\n    }\\n    \\n    free(ipiv);\\n}", "language": "cpp"}	2401452cef3f9ad533e66e95cab909df	common	\N	completed	{"score": 0, "status": "compile_error", "accepted": false, "maxScore": 50}	{"tests": [{"name": "N = 2049", "time": 1290, "score": 0, "memory": 112488, "status": "compile_error", "message": "编译失败：contestant.cpp:5:10: fatal error: cblas.h: No such file or directory", "maxScore": 10}, {"name": "N = 4096", "time": 100, "score": 0, "memory": 44288, "status": "compile_error", "message": "编译失败：contestant.cpp:5:10: fatal error: cblas.h: No such file or directory", "maxScore": 20}, {"name": "N = 8192", "time": 100, "score": 0, "memory": 44416, "status": "compile_error", "message": "编译失败：contestant.cpp:5:10: fatal error: cblas.h: No such file or directory", "maxScore": 20}], "message": "N = 2049：编译失败：contestant.cpp:5:10: fatal error: cblas.h: No such file or directory\\nN = 4096：编译失败：contestant.cpp:5:10: fatal error: cblas.h: No such file or directory\\nN = 8192：编译失败：contestant.cpp:5:10: fatal error: cblas.h: No such file or directory"}	common-1.0.0	\N	2026-10-11 17:28:53.283+00	2026-10-11 17:28:54.964+00
sub_01M4P05RCSRGPE5BMSWBK4PR37	1	lu	kernel	{"source": "#include <stdio.h>\\n#include <stdlib.h>\\n#include <math.h>\\n#include <omp.h>\\n\\n#define BLOCK_SIZE 16\\n\\nvoid mydgemm(double *A,double *B,int n,int bid,int b)\\n{\\n    // 分块矩阵乘法：更新右下角子矩阵\\n    // 计算：A[right_bottom] = A[right_bottom] - A[left_block] * A[top_block]\\n    // \\n    // 优化策略：\\n    // 1. 使用分块（blocking）提高缓存命中率\\n    // 2. 使用 i-k-j 循环顺序，使内存访问更连续\\n    // 3. 小块大小选择 32，这个值可以tune一下\\n    \\n    int block_start = bid * b;          // 当前块的起始位置\\n    int block_end = block_start + b;    // 当前块的结束位置\\n    if (block_end > n) block_end = n;\\n    \\n    int right_start = block_end;        // 右下子矩阵的起始位置\\n    int matrix_size = n - right_start;  // 右下子矩阵的大小\\n    \\n    // 如果右下子矩阵很小，直接使用简单实现\\n    if (matrix_size <= BLOCK_SIZE)\\n    {\\n        // 使用 i-k-j 顺序，更缓存友好\\n        #pragma omp parallel for\\n        for (int i = right_start; i < n; i++)\\n        {\\n            size_t row_offset = (size_t)i * n;  // 优化：预计算行偏移\\n            for (int k = block_start; k < block_end; k++)\\n            {\\n                double a_ik = A[row_offset + k];\\n                size_t k_row_offset = (size_t)k * n;\\n                for (int j = right_start; j < n; j++)\\n                {\\n                    A[row_offset + j] -= a_ik * A[k_row_offset + j];\\n                }\\n            }\\n        }\\n        return;\\n    }\\n    \\n    // 对于大矩阵，使用分块算法\\n    // 分块大小：32×32\\n    int tile_size = BLOCK_SIZE;\\n    \\n    // 外层循环：遍历右下子矩阵的块（可并行）\\n    #pragma omp parallel for schedule(static)\\n    for (int ii = right_start; ii < n; ii += tile_size)\\n    {\\n        for (int jj = right_start; jj < n; jj += tile_size)\\n        {\\n            int i_end = ii + tile_size;\\n            if (i_end > n) i_end = n;\\n            \\n            int j_end = jj + tile_size;\\n            if (j_end > n) j_end = n;\\n            \\n            // 对当前块进行计算\\n            // 遍历 k 维度的所有数据\\n            for (int kk = block_start; kk < block_end; kk += tile_size)\\n            {\\n                int k_end = kk + tile_size;\\n                if (k_end > block_end) k_end = block_end;\\n                \\n                // 内层循环：在小块内使用 i-k-j 顺序\\n                for (int i = ii; i < i_end; i++)\\n                {\\n                    size_t row_offset = (size_t)i * n;  // 优化：预计算行偏移\\n                    for (int k = kk; k < k_end; k++)\\n                    {\\n                        double a_ik = A[row_offset + k];\\n                        size_t k_row_offset = (size_t)k * n;\\n                        // 向量化友好：连续访问内存\\n                        #pragma omp simd\\n                        for (int j = jj; j < j_end; j++)\\n                        {\\n                            A[row_offset + j] -= a_ik * A[k_row_offset + j];\\n                        }\\n                    }\\n                }\\n            }\\n        }\\n    }\\n}\\n\\nint mydgetrf_block(double * __restrict__ A, int * __restrict__ ipiv, int n)\\n{\\n    // 块大小：根据CPU缓存大小tune一下\\n    int b = BLOCK_SIZE;\\n    \\n    /*\\n     * 分块LU分解的核心思想：\\n     * \\n     * 标准算法每次处理1列（k从0到n-1）：\\n     *   for k = 0 to n-1:\\n     *     1. 找主元，交换行\\n     *     2. 计算L[i,k] = A[i,k]/A[k,k]（i > k）\\n     *     3. 更新子矩阵 A[i,j] -= L[i,k]*A[k,j]（i,j > k）\\n     * \\n     * 分块算法每次处理b列（一个块）：\\n     *   for block = 0 to (n/b)-1:\\n     *     1. 对对角块做标准LU分解（处理b列）同时完成对角块下侧的更新。\\n     *     2. 更新对角块右侧（相当于一次性处理b行的上三角更新）\\n     *     3. 更新右下角子矩阵（用块矩阵乘法替代逐元素更新）\\n     */\\n    \\n    // 将n×n矩阵分成多个b×b的块\\n    for (int block_id = 0; block_id * b < n; block_id++)\\n    {\\n        int block_start = block_id * b;                                    // 当前块起始行/列\\n        int block_end = block_start + b;                                   // 当前块结束行/列\\n        if (block_end > n) block_end = n;                                  // 处理最后一个不完整的块\\n        \\n        // ============================================================================\\n        // 步骤1：对当前对角块执行标准LU分解\\n        // ============================================================================\\n        // 这部分与my.c中的mydgetrf完全相同，只是范围限制在[block_start, block_end)\\n        //\\n        // 对应标准算法的：\\n        //   for k = block_start to block_end-1:\\n        //     找主元、交换、计算L、更新块内子矩阵\\n        \\n        for (int k = block_start; k < block_end; k++)\\n        {\\n            // 找主元（从第k行到最后一行）\\n            int pivot_row = k;\\n            double max_val = fabs(A[k * n + k]);            \\n            for (int i = k + 1; i < n; i++) {\\n                double val = fabs(A[i * n + k]);\\n                if (val > max_val) {\\n                    max_val = val;\\n                    pivot_row = i;\\n                }\\n            }\\n            // 奇异性检查\\n            if (max_val < 1e-14) {\\n                return 0;\\n            }\\n            // 记录置换\\n            ipiv[k] = pivot_row;\\n            // 行交换（整行交换，不只是块内）\\n            if (pivot_row != k) {\\n                size_t k_offset = (size_t)k * n;\\n                size_t pivot_offset = (size_t)pivot_row * n;\\n                for (int j = 0; j < n; j++) {\\n                    double tmp = A[k_offset + j];\\n                    A[k_offset + j] = A[pivot_offset + j];\\n                    A[pivot_offset + j] = tmp;\\n                }\\n            }\\n            \\n            // 计算L矩阵的乘数（对所有k行以下的行）\\n            double tmp = 1.0 / A[k * n + k];\\n            for (int i = k + 1,pos=i*n+k; i < n; i++,pos+=n) {\\n                A[pos] = A[pos] * tmp;\\n            }\\n            \\n            // 更新子矩阵（只更新块内的列，即 [k+1, block_end)）\\n            // 对应标准算法中：A[i,j] -= A[i,k] * A[k,j]，但j只到block_end\\n            size_t k_row_offset = (size_t)k * n;\\n            for (int i = k + 1; i < n; i++)\\n            {\\n                size_t i_row_offset = (size_t)i * n;\\n                double multiplier = A[i_row_offset + k];\\n                #pragma omp simd \\n                for (int j = k + 1; j < block_end; j++)\\n                {\\n                    A[i_row_offset + j] -= multiplier * A[k_row_offset + j];\\n                }\\n            }\\n        }\\n        \\n        // 如果还有剩余的矩阵需要更新\\n        if (block_end < n)\\n        {\\n            // ============================================================================\\n            // 步骤2：解三角方程 L11 * U12 = A12，求出U12\\n            // ============================================================================\\n            // L11是刚才得到的对角块（下三角，对角为1）\\n            // A12是对角块右侧的矩阵（block_start:block_end行，block_end:n列）\\n            // 需要用前向替换求解每一列\\n            //\\n            // 对U12的每一列j（从block_end到n）：\\n            //   对该列的每一行i（从block_start到block_end）：\\n            //     U12[i,j] = A12[i,j] - Σ(L11[i,k] * U12[k,j])，k从block_start到i-1\\n            //     因为L11[i,i]=1，不需要除法\\n            \\n            // 可以并行处理每一列\\n            #pragma omp parallel for schedule(static)\\n            for (int j = block_end; j < n; j++)  // 对右侧的每一列\\n            {\\n                for (int i = block_start; i < block_end; i++)  // 从上到下（前向替换）\\n                {\\n                    size_t i_row_offset = (size_t)i * n;\\n                    // A[i,j] -= Σ L11[i,k] * U12[k,j]，k从block_start到i-1\\n                    for (int k = block_start; k < i; k++)\\n                    {\\n                        size_t k_row_offset = (size_t)k * n;\\n                        A[i_row_offset + j] -= A[i_row_offset + k] * A[k_row_offset + j];\\n                    }\\n                    // L11[i,i]=1，所以不需要除法\\n                }\\n            }\\n            \\n            // ============================================================================\\n            // 步骤3：更新右下角子矩阵 A22 = A22 - L21 * U12\\n            // ============================================================================\\n            // 这是Schur补更新，也是分块算法的核心优化\\n            //\\n            // 此时：\\n            // - L21已经计算好了（对角块下方的列）\\n            // - U12已经计算好了（对角块右侧的行）\\n            \\n            mydgemm(A, A, n, block_id, block_end - block_start);\\n        }\\n    }\\n    \\n    return 1;\\n}\\n\\nvoid mydtrsv(char UPLO, double* __restrict__ A, double* __restrict__  B, int n, int* __restrict__ ipiv)\\n{\\n    if (UPLO == 'L' || UPLO == 'l')\\n    {\\n        // 1. Pivoting\\n        for (int i = 0; i < n; i++) {\\n            if (ipiv[i] != i) {\\n                double tmp = B[i];\\n                B[i] = B[ipiv[i]];\\n                B[ipiv[i]] = tmp;\\n            }\\n        }\\n        \\n        // 2. Forward\\n        for (int i = 0; i < n; i++) {\\n            double sum = 0.0;\\n            size_t i_offset = (size_t)i * n;\\n            \\n            // 纯串行，但强制 SIMD\\n            #pragma omp simd reduction(+:sum)\\n            for (int j = 0; j < i; j++) {\\n                sum += A[i_offset + j] * B[j];\\n            }\\n            B[i] -= sum;\\n        }\\n    }\\n    else\\n    {\\n        // 3. Backward\\n        for (int i = n - 1; i >= 0; i--) {\\n            double sum = 0.0;\\n            size_t i_offset = (size_t)i * n;\\n            \\n            #pragma omp simd reduction(+:sum)\\n            for (int j = i + 1; j < n; j++) {\\n                sum += A[i_offset + j] * B[j];\\n            }\\n            B[i] -= sum;\\n            B[i] /= A[i_offset + i];\\n        }\\n    }\\n}\\nvoid my_solver(int n, double *A, double *b)\\n{\\n    int *ipiv=(int*)malloc(n*sizeof(int));\\n    for (int i=0;i<n;i++)\\n        ipiv[i]=i;\\n    if (mydgetrf_block(A,ipiv,n)==0) \\n    {\\n        printf(\\"LU factorization failed: coefficient matrix is singular.\\\\n\\");\\n        free(ipiv);\\n        return;\\n    }\\n    mydtrsv('L',A,b,n,ipiv);\\n    mydtrsv('U',A,b,n,ipiv);\\n    free(ipiv);\\n}", "language": "cpp"}	bc39c6fd16f3eb88b4d84aaa2d6ac733	common	\N	completed	{"score": 48, "status": "partial", "accepted": false, "maxScore": 50}	{"tests": [{"name": "N = 2049", "time": 1650, "score": 8, "memory": 112412, "status": "partial", "message": "N=2049 用时 0.237046s（满分成绩 0.22s，上限 0.7s），相对残差 6.714785e-13，25.66 GFLOPS", "maxScore": 10}, {"name": "N = 4096", "time": 2540, "score": 20, "memory": 134400, "status": "accepted", "message": "N=4096 用时 1.857354s（满分成绩 2.2s，上限 7s），相对残差 5.112261e-12，25.16 GFLOPS", "maxScore": 20}, {"name": "N = 8192", "time": 16320, "score": 20, "memory": 527488, "status": "accepted", "message": "N=8192 用时 13.406830s（满分成绩 14s，上限 45s），相对残差 1.587276e-11，27.69 GFLOPS", "maxScore": 20}], "message": "N = 2049：N=2049 用时 0.237046s（满分成绩 0.22s，上限 0.7s），相对残差 6.714785e-13，25.66 GFLOPS\\nN = 4096：N=4096 用时 1.857354s（满分成绩 2.2s，上限 7s），相对残差 5.112261e-12，25.16 GFLOPS\\nN = 8192：N=8192 用时 13.406830s（满分成绩 14s，上限 45s），相对残差 1.587276e-11，27.69 GFLOPS"}	common-1.0.0	\N	2026-10-11 17:29:08.764+00	2026-10-11 17:34:31.969+00
sub_01M4P0VHJPCYWPBD7ETZEE7NRN	1	lu	kernel	{"source": "// The contestant file: implement my_solver here, and do NOT write main --\\n// driver.cpp already owns it. The judge overwrites this file with payload.source.\\n//\\n// What ships here is the naive implementation from the statement (single\\n// threaded, no blocking). It keeps the problem compilable out of the box and is\\n// the starting point for local testing. It is correct but slow: at N=2049 it\\n// already exceeds the 0.5 s limit, so submitting it unchanged scores 0 -- which\\n// is the whole point of scoring against the per-test full-mark time.\\n#include <cstdio>\\n#include <cstdlib>\\n#include <cmath>\\n\\nint mydgetrf(double *A,int *ipiv,int n)\\n{\\n    // LU decomposition with partial pivoting\\n    // A is stored in row-major format\\n    // On exit, A contains L (below diagonal with unit diagonal) and U (on and above diagonal)\\n    \\n    for (int k = 0; k < n; k++)\\n    {\\n        // Find pivot (max element in column k from row k to n-1)\\n        int pivot_row = k;\\n        double max_val = fabs(A[k * n + k]);\\n        \\n        for (int i = k + 1; i < n; i++)\\n        {\\n            double val = fabs(A[i * n + k]);\\n            if (val > max_val)\\n            {\\n                max_val = val;\\n                pivot_row = i;\\n            }\\n        }\\n        \\n        // Check for singularity\\n        if (max_val < 1e-14)\\n        {\\n            return 0; // Matrix is singular\\n        }\\n        \\n        // Record pivot\\n        ipiv[k] = pivot_row;\\n        \\n        // Swap rows k and pivot_row if needed\\n        if (pivot_row != k)\\n        {\\n            for (int j = 0; j < n; j++)\\n            {\\n                double tmp = A[k * n + j];\\n                A[k * n + j] = A[pivot_row * n + j];\\n                A[pivot_row * n + j] = tmp;\\n            }\\n        }\\n        \\n        // Compute multipliers and update submatrix\\n        for (int i = k + 1; i < n; i++)\\n        {\\n            // Compute multiplier L[i,k]\\n            A[i * n + k] = A[i * n + k] / A[k * n + k];\\n            \\n            // Update row i: A[i,k+1:n] -= L[i,k] * A[k,k+1:n]\\n            for (int j = k + 1; j < n; j++)\\n            {\\n                A[i * n + j] -= A[i * n + k] * A[k * n + j];\\n            }\\n        }\\n    }\\n    \\n    return 1;\\n}\\n\\nvoid mydtrsv(char UPLO,double *A,double *B,int n,int *ipiv)\\n{\\n    // Solve triangular system\\n    // A is in row-major format\\n    // UPLO='L': solve Lx=B (L has unit diagonal)\\n    // UPLO='U': solve Ux=B (U has non-unit diagonal)\\n    \\n    if (UPLO == 'L' || UPLO == 'l')\\n    {\\n        // Forward substitution for lower triangular system with unit diagonal\\n        // Apply pivoting first\\n        for (int i = 0; i < n; i++)\\n        {\\n            if (ipiv[i] != i)\\n            {\\n                double tmp = B[i];\\n                B[i] = B[ipiv[i]];\\n                B[ipiv[i]] = tmp;\\n            }\\n        }\\n        \\n        // Solve Lx=B where L has unit diagonal\\n        for (int i = 0; i < n; i++)\\n        {\\n            for (int j = 0; j < i; j++)\\n            {\\n                B[i] -= A[i * n + j] * B[j];\\n            }\\n            // Note: L[i,i] = 1, so no division needed\\n        }\\n    }\\n    else if (UPLO == 'U' || UPLO == 'u')\\n    {\\n        // Backward substitution for upper triangular system\\n        // Solve Ux=B\\n        for (int i = n - 1; i >= 0; i--)\\n        {\\n            for (int j = i + 1; j < n; j++)\\n            {\\n                B[i] -= A[i * n + j] * B[j];\\n            }\\n            B[i] /= A[i * n + i];\\n        }\\n    }\\n}\\n\\nvoid my_solver(int n, double *A, double *b)\\n{\\n    int *ipiv=(int*)malloc(n*sizeof(int));\\n    for (int i=0;i<n;i++)\\n        ipiv[i]=i;\\n    if (mydgetrf(A,ipiv,n)==0) \\n    {\\n        printf(\\"LU factorization failed: coefficient matrix is singular.\\\\n\\");\\n        free(ipiv);\\n        return;\\n    }\\n    mydtrsv('L',A,b,n,ipiv);\\n    mydtrsv('U',A,b,n,ipiv);\\n    free(ipiv);\\n}", "language": "cpp"}	9e5a26fd72b54eb4ae077ef9acb3b5d1	common	\N	completed	{"score": 0, "status": "time_limit_exceeded", "accepted": false, "maxScore": 50}	{"tests": [{"name": "N = 2049", "time": 2210, "score": 0, "memory": 112448, "status": "time_limit_exceeded", "message": "N=2049 用时 0.873257s，超过 0.7s 的限制", "maxScore": 10}, {"name": "N = 4096", "time": 9620, "score": 0, "memory": 134144, "status": "time_limit_exceeded", "message": "N=4096 用时 8.970402s，超过 7s 的限制", "maxScore": 20}, {"name": "N = 8192", "time": 53501, "score": 0, "memory": 0, "status": "time_limit_exceeded", "maxScore": 20}], "message": "N = 2049：N=2049 用时 0.873257s，超过 0.7s 的限制\\nN = 4096：N=4096 用时 8.970402s，超过 7s 的限制"}	common-1.0.0	\N	2026-10-11 17:41:02.68+00	2026-10-11 17:42:08.229+00
sub_01M4P0ZFJAYCC1ZFW8TSZ8YNNW	1	lu	kernel	{"source": "#include <stdio.h>\\n#include <stdlib.h>\\n#include <math.h>\\n#include <omp.h>\\n\\n#define BLOCK_SIZE 16\\n\\nvoid mydgemm(double *A,double *B,int n,int bid,int b)\\n{\\n    // 分块矩阵乘法：更新右下角子矩阵\\n    // 计算：A[right_bottom] = A[right_bottom] - A[left_block] * A[top_block]\\n    // \\n    // 优化策略：\\n    // 1. 使用分块（blocking）提高缓存命中率\\n    // 2. 使用 i-k-j 循环顺序，使内存访问更连续\\n    // 3. 小块大小选择 32，这个值可以tune一下\\n    \\n    int block_start = bid * b;          // 当前块的起始位置\\n    int block_end = block_start + b;    // 当前块的结束位置\\n    if (block_end > n) block_end = n;\\n    \\n    int right_start = block_end;        // 右下子矩阵的起始位置\\n    int matrix_size = n - right_start;  // 右下子矩阵的大小\\n    \\n    // 如果右下子矩阵很小，直接使用简单实现\\n    if (matrix_size <= BLOCK_SIZE)\\n    {\\n        // 使用 i-k-j 顺序，更缓存友好\\n        #pragma omp parallel for\\n        for (int i = right_start; i < n; i++)\\n        {\\n            size_t row_offset = (size_t)i * n;  // 优化：预计算行偏移\\n            for (int k = block_start; k < block_end; k++)\\n            {\\n                double a_ik = A[row_offset + k];\\n                size_t k_row_offset = (size_t)k * n;\\n                for (int j = right_start; j < n; j++)\\n                {\\n                    A[row_offset + j] -= a_ik * A[k_row_offset + j];\\n                }\\n            }\\n        }\\n        return;\\n    }\\n    \\n    // 对于大矩阵，使用分块算法\\n    // 分块大小：32×32\\n    int tile_size = BLOCK_SIZE;\\n    \\n    // 外层循环：遍历右下子矩阵的块（可并行）\\n    #pragma omp parallel for schedule(static)\\n    for (int ii = right_start; ii < n; ii += tile_size)\\n    {\\n        for (int jj = right_start; jj < n; jj += tile_size)\\n        {\\n            int i_end = ii + tile_size;\\n            if (i_end > n) i_end = n;\\n            \\n            int j_end = jj + tile_size;\\n            if (j_end > n) j_end = n;\\n            \\n            // 对当前块进行计算\\n            // 遍历 k 维度的所有数据\\n            for (int kk = block_start; kk < block_end; kk += tile_size)\\n            {\\n                int k_end = kk + tile_size;\\n                if (k_end > block_end) k_end = block_end;\\n                \\n                // 内层循环：在小块内使用 i-k-j 顺序\\n                for (int i = ii; i < i_end; i++)\\n                {\\n                    size_t row_offset = (size_t)i * n;  // 优化：预计算行偏移\\n                    for (int k = kk; k < k_end; k++)\\n                    {\\n                        double a_ik = A[row_offset + k];\\n                        size_t k_row_offset = (size_t)k * n;\\n                        // 向量化友好：连续访问内存\\n                        #pragma omp simd\\n                        for (int j = jj; j < j_end; j++)\\n                        {\\n                            A[row_offset + j] -= a_ik * A[k_row_offset + j];\\n                        }\\n                    }\\n                }\\n            }\\n        }\\n    }\\n}\\n\\nint mydgetrf_block(double * __restrict__ A, int * __restrict__ ipiv, int n)\\n{\\n    // 块大小：根据CPU缓存大小tune一下\\n    int b = BLOCK_SIZE;\\n    \\n    /*\\n     * 分块LU分解的核心思想：\\n     * \\n     * 标准算法每次处理1列（k从0到n-1）：\\n     *   for k = 0 to n-1:\\n     *     1. 找主元，交换行\\n     *     2. 计算L[i,k] = A[i,k]/A[k,k]（i > k）\\n     *     3. 更新子矩阵 A[i,j] -= L[i,k]*A[k,j]（i,j > k）\\n     * \\n     * 分块算法每次处理b列（一个块）：\\n     *   for block = 0 to (n/b)-1:\\n     *     1. 对对角块做标准LU分解（处理b列）同时完成对角块下侧的更新。\\n     *     2. 更新对角块右侧（相当于一次性处理b行的上三角更新）\\n     *     3. 更新右下角子矩阵（用块矩阵乘法替代逐元素更新）\\n     */\\n    \\n    // 将n×n矩阵分成多个b×b的块\\n    for (int block_id = 0; block_id * b < n; block_id++)\\n    {\\n        int block_start = block_id * b;                                    // 当前块起始行/列\\n        int block_end = block_start + b;                                   // 当前块结束行/列\\n        if (block_end > n) block_end = n;                                  // 处理最后一个不完整的块\\n        \\n        // ============================================================================\\n        // 步骤1：对当前对角块执行标准LU分解\\n        // ============================================================================\\n        // 这部分与my.c中的mydgetrf完全相同，只是范围限制在[block_start, block_end)\\n        //\\n        // 对应标准算法的：\\n        //   for k = block_start to block_end-1:\\n        //     找主元、交换、计算L、更新块内子矩阵\\n        \\n        for (int k = block_start; k < block_end; k++)\\n        {\\n            // 找主元（从第k行到最后一行）\\n            int pivot_row = k;\\n            double max_val = fabs(A[k * n + k]);            \\n            for (int i = k + 1; i < n; i++) {\\n                double val = fabs(A[i * n + k]);\\n                if (val > max_val) {\\n                    max_val = val;\\n                    pivot_row = i;\\n                }\\n            }\\n            // 奇异性检查\\n            if (max_val < 1e-14) {\\n                return 0;\\n            }\\n            // 记录置换\\n            ipiv[k] = pivot_row;\\n            // 行交换（整行交换，不只是块内）\\n            if (pivot_row != k) {\\n                size_t k_offset = (size_t)k * n;\\n                size_t pivot_offset = (size_t)pivot_row * n;\\n                for (int j = 0; j < n; j++) {\\n                    double tmp = A[k_offset + j];\\n                    A[k_offset + j] = A[pivot_offset + j];\\n                    A[pivot_offset + j] = tmp;\\n                }\\n            }\\n            \\n            // 计算L矩阵的乘数（对所有k行以下的行）\\n            double tmp = 1.0 / A[k * n + k];\\n            for (int i = k + 1,pos=i*n+k; i < n; i++,pos+=n) {\\n                A[pos] = A[pos] * tmp;\\n            }\\n            \\n            // 更新子矩阵（只更新块内的列，即 [k+1, block_end)）\\n            // 对应标准算法中：A[i,j] -= A[i,k] * A[k,j]，但j只到block_end\\n            size_t k_row_offset = (size_t)k * n;\\n            for (int i = k + 1; i < n; i++)\\n            {\\n                size_t i_row_offset = (size_t)i * n;\\n                double multiplier = A[i_row_offset + k];\\n                #pragma omp simd \\n                for (int j = k + 1; j < block_end; j++)\\n                {\\n                    A[i_row_offset + j] -= multiplier * A[k_row_offset + j];\\n                }\\n            }\\n        }\\n        \\n        // 如果还有剩余的矩阵需要更新\\n        if (block_end < n)\\n        {\\n            // ============================================================================\\n            // 步骤2：解三角方程 L11 * U12 = A12，求出U12\\n            // ============================================================================\\n            // L11是刚才得到的对角块（下三角，对角为1）\\n            // A12是对角块右侧的矩阵（block_start:block_end行，block_end:n列）\\n            // 需要用前向替换求解每一列\\n            //\\n            // 对U12的每一列j（从block_end到n）：\\n            //   对该列的每一行i（从block_start到block_end）：\\n            //     U12[i,j] = A12[i,j] - Σ(L11[i,k] * U12[k,j])，k从block_start到i-1\\n            //     因为L11[i,i]=1，不需要除法\\n            \\n            // 可以并行处理每一列\\n            #pragma omp parallel for schedule(static)\\n            for (int j = block_end; j < n; j++)  // 对右侧的每一列\\n            {\\n                for (int i = block_start; i < block_end; i++)  // 从上到下（前向替换）\\n                {\\n                    size_t i_row_offset = (size_t)i * n;\\n                    // A[i,j] -= Σ L11[i,k] * U12[k,j]，k从block_start到i-1\\n                    for (int k = block_start; k < i; k++)\\n                    {\\n                        size_t k_row_offset = (size_t)k * n;\\n                        A[i_row_offset + j] -= A[i_row_offset + k] * A[k_row_offset + j];\\n                    }\\n                    // L11[i,i]=1，所以不需要除法\\n                }\\n            }\\n            \\n            // ============================================================================\\n            // 步骤3：更新右下角子矩阵 A22 = A22 - L21 * U12\\n            // ============================================================================\\n            // 这是Schur补更新，也是分块算法的核心优化\\n            //\\n            // 此时：\\n            // - L21已经计算好了（对角块下方的列）\\n            // - U12已经计算好了（对角块右侧的行）\\n            \\n            mydgemm(A, A, n, block_id, block_end - block_start);\\n        }\\n    }\\n    \\n    return 1;\\n}\\n\\nvoid mydtrsv(char UPLO, double* __restrict__ A, double* __restrict__  B, int n, int* __restrict__ ipiv)\\n{\\n    if (UPLO == 'L' || UPLO == 'l')\\n    {\\n        // 1. Pivoting\\n        for (int i = 0; i < n; i++) {\\n            if (ipiv[i] != i) {\\n                double tmp = B[i];\\n                B[i] = B[ipiv[i]];\\n                B[ipiv[i]] = tmp;\\n            }\\n        }\\n        \\n        // 2. Forward\\n        for (int i = 0; i < n; i++) {\\n            double sum = 0.0;\\n            size_t i_offset = (size_t)i * n;\\n            \\n            // 纯串行，但强制 SIMD\\n            #pragma omp simd reduction(+:sum)\\n            for (int j = 0; j < i; j++) {\\n                sum += A[i_offset + j] * B[j];\\n            }\\n            B[i] -= sum;\\n        }\\n    }\\n    else\\n    {\\n        // 3. Backward\\n        for (int i = n - 1; i >= 0; i--) {\\n            double sum = 0.0;\\n            size_t i_offset = (size_t)i * n;\\n            \\n            #pragma omp simd reduction(+:sum)\\n            for (int j = i + 1; j < n; j++) {\\n                sum += A[i_offset + j] * B[j];\\n            }\\n            B[i] -= sum;\\n            B[i] /= A[i_offset + i];\\n        }\\n    }\\n}\\nvoid my_solver(int n, double *A, double *b)\\n{\\n    int *ipiv=(int*)malloc(n*sizeof(int));\\n    for (int i=0;i<n;i++)\\n        ipiv[i]=i;\\n    if (mydgetrf_block(A,ipiv,n)==0) \\n    {\\n        printf(\\"LU factorization failed: coefficient matrix is singular.\\\\n\\");\\n        free(ipiv);\\n        return;\\n    }\\n    mydtrsv('L',A,b,n,ipiv);\\n    mydtrsv('U',A,b,n,ipiv);\\n    free(ipiv);\\n}", "language": "cpp"}	d06d3c5fa8e97fec7f796dde0905745e	common	\N	completed	{"score": 50, "status": "accepted", "accepted": true, "maxScore": 50}	{"tests": [{"name": "N = 2049", "time": 1720, "score": 10, "memory": 112276, "status": "accepted", "message": "N=2049 用时 0.191533s（满分成绩 0.22s，上限 0.7s），相对残差 6.373702e-13，32.18 GFLOPS", "maxScore": 10}, {"name": "N = 4096", "time": 2650, "score": 20, "memory": 134400, "status": "accepted", "message": "N=4096 用时 1.953840s（满分成绩 2.2s，上限 7s），相对残差 8.524147e-12，23.92 GFLOPS", "maxScore": 20}, {"name": "N = 8192", "time": 15590, "score": 20, "memory": 527744, "status": "accepted", "message": "N=8192 用时 12.488797s（满分成绩 14s，上限 45s），相对残差 3.771195e-11，30.34 GFLOPS", "maxScore": 20}], "message": "N = 2049：N=2049 用时 0.191533s（满分成绩 0.22s，上限 0.7s），相对残差 6.373702e-13，32.18 GFLOPS\\nN = 4096：N=4096 用时 1.953840s（满分成绩 2.2s，上限 7s），相对残差 8.524147e-12，23.92 GFLOPS\\nN = 8192：N=8192 用时 12.488797s（满分成绩 14s，上限 45s），相对残差 3.771195e-11，30.34 GFLOPS"}	common-1.0.0	\N	2026-10-11 17:43:11.693+00	2026-10-11 17:43:31.956+00
sub_01M4R3A4E70WQED7WRSK4VGA83	1	lu	kernel	{"source": "#include <stdio.h>\\n#include <stdlib.h>\\n#include <math.h>\\n#include <omp.h>\\n\\n#define BLOCK_SIZE 16\\n\\nvoid mydgemm(double *A,double *B,int n,int bid,int b)\\n{\\n    // 分块矩阵乘法：更新右下角子矩阵\\n    // 计算：A[right_bottom] = A[right_bottom] - A[left_block] * A[top_block]\\n    // \\n    // 优化策略：\\n    // 1. 使用分块（blocking）提高缓存命中率\\n    // 2. 使用 i-k-j 循环顺序，使内存访问更连续\\n    // 3. 小块大小选择 32，这个值可以tune一下\\n    \\n    int block_start = bid * b;          // 当前块的起始位置\\n    int block_end = block_start + b;    // 当前块的结束位置\\n    if (block_end > n) block_end = n;\\n    \\n    int right_start = block_end;        // 右下子矩阵的起始位置\\n    int matrix_size = n - right_start;  // 右下子矩阵的大小\\n    \\n    // 如果右下子矩阵很小，直接使用简单实现\\n    if (matrix_size <= BLOCK_SIZE)\\n    {\\n        // 使用 i-k-j 顺序，更缓存友好\\n        #pragma omp parallel for\\n        for (int i = right_start; i < n; i++)\\n        {\\n            size_t row_offset = (size_t)i * n;  // 优化：预计算行偏移\\n            for (int k = block_start; k < block_end; k++)\\n            {\\n                double a_ik = A[row_offset + k];\\n                size_t k_row_offset = (size_t)k * n;\\n                for (int j = right_start; j < n; j++)\\n                {\\n                    A[row_offset + j] -= a_ik * A[k_row_offset + j];\\n                }\\n            }\\n        }\\n        return;\\n    }\\n    \\n    // 对于大矩阵，使用分块算法\\n    // 分块大小：32×32\\n    int tile_size = BLOCK_SIZE;\\n    \\n    // 外层循环：遍历右下子矩阵的块（可并行）\\n    #pragma omp parallel for schedule(static)\\n    for (int ii = right_start; ii < n; ii += tile_size)\\n    {\\n        for (int jj = right_start; jj < n; jj += tile_size)\\n        {\\n            int i_end = ii + tile_size;\\n            if (i_end > n) i_end = n;\\n            \\n            int j_end = jj + tile_size;\\n            if (j_end > n) j_end = n;\\n            \\n            // 对当前块进行计算\\n            // 遍历 k 维度的所有数据\\n            for (int kk = block_start; kk < block_end; kk += tile_size)\\n            {\\n                int k_end = kk + tile_size;\\n                if (k_end > block_end) k_end = block_end;\\n                \\n                // 内层循环：在小块内使用 i-k-j 顺序\\n                for (int i = ii; i < i_end; i++)\\n                {\\n                    size_t row_offset = (size_t)i * n;  // 优化：预计算行偏移\\n                    for (int k = kk; k < k_end; k++)\\n                    {\\n                        double a_ik = A[row_offset + k];\\n                        size_t k_row_offset = (size_t)k * n;\\n                        // 向量化友好：连续访问内存\\n                        #pragma omp simd\\n                        for (int j = jj; j < j_end; j++)\\n                        {\\n                            A[row_offset + j] -= a_ik * A[k_row_offset + j];\\n                        }\\n                    }\\n                }\\n            }\\n        }\\n    }\\n}\\n\\nint mydgetrf_block(double * __restrict__ A, int * __restrict__ ipiv, int n)\\n{\\n    // 块大小：根据CPU缓存大小tune一下\\n    int b = BLOCK_SIZE;\\n    \\n    /*\\n     * 分块LU分解的核心思想：\\n     * \\n     * 标准算法每次处理1列（k从0到n-1）：\\n     *   for k = 0 to n-1:\\n     *     1. 找主元，交换行\\n     *     2. 计算L[i,k] = A[i,k]/A[k,k]（i > k）\\n     *     3. 更新子矩阵 A[i,j] -= L[i,k]*A[k,j]（i,j > k）\\n     * \\n     * 分块算法每次处理b列（一个块）：\\n     *   for block = 0 to (n/b)-1:\\n     *     1. 对对角块做标准LU分解（处理b列）同时完成对角块下侧的更新。\\n     *     2. 更新对角块右侧（相当于一次性处理b行的上三角更新）\\n     *     3. 更新右下角子矩阵（用块矩阵乘法替代逐元素更新）\\n     */\\n    \\n    // 将n×n矩阵分成多个b×b的块\\n    for (int block_id = 0; block_id * b < n; block_id++)\\n    {\\n        int block_start = block_id * b;                                    // 当前块起始行/列\\n        int block_end = block_start + b;                                   // 当前块结束行/列\\n        if (block_end > n) block_end = n;                                  // 处理最后一个不完整的块\\n        \\n        // ============================================================================\\n        // 步骤1：对当前对角块执行标准LU分解\\n        // ============================================================================\\n        // 这部分与my.c中的mydgetrf完全相同，只是范围限制在[block_start, block_end)\\n        //\\n        // 对应标准算法的：\\n        //   for k = block_start to block_end-1:\\n        //     找主元、交换、计算L、更新块内子矩阵\\n        \\n        for (int k = block_start; k < block_end; k++)\\n        {\\n            // 找主元（从第k行到最后一行）\\n            int pivot_row = k;\\n            double max_val = fabs(A[k * n + k]);            \\n            for (int i = k + 1; i < n; i++) {\\n                double val = fabs(A[i * n + k]);\\n                if (val > max_val) {\\n                    max_val = val;\\n                    pivot_row = i;\\n                }\\n            }\\n            // 奇异性检查\\n            if (max_val < 1e-14) {\\n                return 0;\\n            }\\n            // 记录置换\\n            ipiv[k] = pivot_row;\\n            // 行交换（整行交换，不只是块内）\\n            if (pivot_row != k) {\\n                size_t k_offset = (size_t)k * n;\\n                size_t pivot_offset = (size_t)pivot_row * n;\\n                for (int j = 0; j < n; j++) {\\n                    double tmp = A[k_offset + j];\\n                    A[k_offset + j] = A[pivot_offset + j];\\n                    A[pivot_offset + j] = tmp;\\n                }\\n            }\\n            \\n            // 计算L矩阵的乘数（对所有k行以下的行）\\n            double tmp = 1.0 / A[k * n + k];\\n            for (int i = k + 1,pos=i*n+k; i < n; i++,pos+=n) {\\n                A[pos] = A[pos] * tmp;\\n            }\\n            \\n            // 更新子矩阵（只更新块内的列，即 [k+1, block_end)）\\n            // 对应标准算法中：A[i,j] -= A[i,k] * A[k,j]，但j只到block_end\\n            size_t k_row_offset = (size_t)k * n;\\n            for (int i = k + 1; i < n; i++)\\n            {\\n                size_t i_row_offset = (size_t)i * n;\\n                double multiplier = A[i_row_offset + k];\\n                #pragma omp simd \\n                for (int j = k + 1; j < block_end; j++)\\n                {\\n                    A[i_row_offset + j] -= multiplier * A[k_row_offset + j];\\n                }\\n            }\\n        }\\n        \\n        // 如果还有剩余的矩阵需要更新\\n        if (block_end < n)\\n        {\\n            // ============================================================================\\n            // 步骤2：解三角方程 L11 * U12 = A12，求出U12\\n            // ============================================================================\\n            // L11是刚才得到的对角块（下三角，对角为1）\\n            // A12是对角块右侧的矩阵（block_start:block_end行，block_end:n列）\\n            // 需要用前向替换求解每一列\\n            //\\n            // 对U12的每一列j（从block_end到n）：\\n            //   对该列的每一行i（从block_start到block_end）：\\n            //     U12[i,j] = A12[i,j] - Σ(L11[i,k] * U12[k,j])，k从block_start到i-1\\n            //     因为L11[i,i]=1，不需要除法\\n            \\n            // 可以并行处理每一列\\n            #pragma omp parallel for schedule(static)\\n            for (int j = block_end; j < n; j++)  // 对右侧的每一列\\n            {\\n                for (int i = block_start; i < block_end; i++)  // 从上到下（前向替换）\\n                {\\n                    size_t i_row_offset = (size_t)i * n;\\n                    // A[i,j] -= Σ L11[i,k] * U12[k,j]，k从block_start到i-1\\n                    for (int k = block_start; k < i; k++)\\n                    {\\n                        size_t k_row_offset = (size_t)k * n;\\n                        A[i_row_offset + j] -= A[i_row_offset + k] * A[k_row_offset + j];\\n                    }\\n                    // L11[i,i]=1，所以不需要除法\\n                }\\n            }\\n            \\n            // ============================================================================\\n            // 步骤3：更新右下角子矩阵 A22 = A22 - L21 * U12\\n            // ============================================================================\\n            // 这是Schur补更新，也是分块算法的核心优化\\n            //\\n            // 此时：\\n            // - L21已经计算好了（对角块下方的列）\\n            // - U12已经计算好了（对角块右侧的行）\\n            \\n            mydgemm(A, A, n, block_id, block_end - block_start);\\n        }\\n    }\\n    \\n    return 1;\\n}\\n\\nvoid mydtrsv(char UPLO, double* __restrict__ A, double* __restrict__  B, int n, int* __restrict__ ipiv)\\n{\\n    if (UPLO == 'L' || UPLO == 'l')\\n    {\\n        // 1. Pivoting\\n        for (int i = 0; i < n; i++) {\\n            if (ipiv[i] != i) {\\n                double tmp = B[i];\\n                B[i] = B[ipiv[i]];\\n                B[ipiv[i]] = tmp;\\n            }\\n        }\\n        \\n        // 2. Forward\\n        for (int i = 0; i < n; i++) {\\n            double sum = 0.0;\\n            size_t i_offset = (size_t)i * n;\\n            \\n            // 纯串行，但强制 SIMD\\n            #pragma omp simd reduction(+:sum)\\n            for (int j = 0; j < i; j++) {\\n                sum += A[i_offset + j] * B[j];\\n            }\\n            B[i] -= sum;\\n        }\\n    }\\n    else\\n    {\\n        // 3. Backward\\n        for (int i = n - 1; i >= 0; i--) {\\n            double sum = 0.0;\\n            size_t i_offset = (size_t)i * n;\\n            \\n            #pragma omp simd reduction(+:sum)\\n            for (int j = i + 1; j < n; j++) {\\n                sum += A[i_offset + j] * B[j];\\n            }\\n            B[i] -= sum;\\n            B[i] /= A[i_offset + i];\\n        }\\n    }\\n}\\nvoid my_solver(int n, double *A, double *b)\\n{\\n    int *ipiv=(int*)malloc(n*sizeof(int));\\n    for (int i=0;i<n;i++)\\n        ipiv[i]=i;\\n    if (mydgetrf_block(A,ipiv,n)==0) \\n    {\\n        printf(\\"LU factorization failed: coefficient matrix is singular.\\\\n\\");\\n        free(ipiv);\\n        return;\\n    }\\n    mydtrsv('L',A,b,n,ipiv);\\n    mydtrsv('U',A,b,n,ipiv);\\n    free(ipiv);\\n}", "language": "cpp"}	69c2eac6dd60d6348103f029963188c7	common	\N	completed	{"score": 48, "status": "partial", "accepted": false, "maxScore": 50}	{"tests": [{"name": "N = 2049", "time": 1950, "score": 8, "memory": 112604, "status": "partial", "message": "N=2049 用时 0.239911s（满分成绩 0.22s，上限 0.7s），相对残差 1.074503e-12，24.94 GFLOPS", "maxScore": 10}, {"name": "N = 4096", "time": 2870, "score": 20, "memory": 134400, "status": "accepted", "message": "N=4096 用时 2.176447s（满分成绩 2.2s，上限 7s），相对残差 3.170275e-12，21.93 GFLOPS", "maxScore": 20}, {"name": "N = 8192", "time": 15880, "score": 20, "memory": 527744, "status": "accepted", "message": "N=8192 用时 13.088194s（满分成绩 14s，上限 45s），相对残差 1.173881e-11，28.59 GFLOPS", "maxScore": 20}], "message": "N = 2049：N=2049 用时 0.239911s（满分成绩 0.22s，上限 0.7s），相对残差 1.074503e-12，24.94 GFLOPS\\nN = 4096：N=4096 用时 2.176447s（满分成绩 2.2s，上限 7s），相对残差 3.170275e-12，21.93 GFLOPS\\nN = 8192：N=8192 用时 13.088194s（满分成绩 14s，上限 45s），相对残差 1.173881e-11，28.59 GFLOPS"}	common-1.0.0	\N	2026-10-12 13:02:26.762+00	2026-10-12 13:02:48.629+00
sub_01M4TFHR7WEKE9CGEZJEYZR609	1	sssp-hpc	kernel	{"source": "#include <algorithm>\\n#include <chrono>\\n#include <cstdint>\\n#include <cstdio>\\n#include <cstdlib>\\n#include <queue>\\n#include <random>\\n#include <vector>\\n#include <omp.h>\\n#include <iostream>\\n\\nconst uint64_t MAX_WEIGHT = 1e7;\\nconst uint64_t INF = 1e18;\\n\\nvoid calculate(uint32_t n, uint32_t m, uint32_t *edges, uint64_t *dis);\\n\\n// Identical to the upstream generator, including the dist(0, i) that keeps the\\n// first n-1 edges a tree and so guarantees every vertex is reachable.\\nstatic void random_edges(uint32_t n, uint32_t m, uint32_t seed,\\n                         std::vector<uint32_t> &edges) {\\n    std::mt19937_64 gen(seed);\\n    std::uniform_int_distribution<uint32_t> gen_node(0, n - 1);\\n    std::uniform_int_distribution<uint32_t> gen_weight(1, MAX_WEIGHT);\\n\\n    for (uint32_t i = 0; i < n - 1; ++i) {\\n        uint32_t u = std::uniform_int_distribution<size_t>(0, i)(gen);\\n        uint32_t v = i + 1;\\n        uint32_t w = gen_weight(gen);\\n        edges[i * 3] = u;\\n        edges[i * 3 + 1] = v;\\n        edges[i * 3 + 2] = w;\\n    }\\n    for (uint32_t i = n - 1; i < m; ++i) {\\n        uint32_t u = gen_node(gen);\\n        uint32_t v = gen_node(gen);\\n        uint32_t w = gen_weight(gen);\\n        edges[i * 3] = u;\\n        edges[i * 3 + 1] = v;\\n        edges[i * 3 + 2] = w;\\n    }\\n}\\n\\n// The judge cannot use the upstream std solution as an oracle: it relaxes with\\n// relaxed atomics across threads, so its byte output is not stable. Serial\\n// Dijkstra is deterministic, which is what a reference has to be.\\nstatic void reference(uint32_t n, uint32_t m, const std::vector<uint32_t> &edges,\\n                      std::vector<uint64_t> &dis) {\\n    struct arc { uint32_t to, w; };\\n    std::vector<std::vector<arc>> adj(n);\\n    for (uint32_t i = 0; i < m; ++i) {\\n        adj[edges[i * 3]].push_back({edges[i * 3 + 1], edges[i * 3 + 2]});\\n    }\\n    using item = std::pair<uint64_t, uint32_t>;\\n    std::priority_queue<item, std::vector<item>, std::greater<item>> pq;\\n    std::vector<char> done(n, 0);\\n    dis.assign(n, INF);\\n    dis[0] = 0;\\n    pq.push({0, 0});\\n    while (!pq.empty()) {\\n        auto [d, u] = pq.top();\\n        pq.pop();\\n        if (done[u]) continue;\\n        done[u] = 1;\\n        for (const arc &a : adj[u]) {\\n            uint64_t nd = d + a.w;\\n            if (nd < dis[a.to]) { dis[a.to] = nd; pq.push({nd, a.to}); }\\n        }\\n    }\\n}\\n\\nvoid setup_omp_env() {\\\\\\n    putenv((char*)\\"OMP_NUM_THREADS=16\\");\\n    putenv((char*)\\"OMP_PROC_BIND=close\\");\\n    putenv((char*)\\"OMP_PLACES=cores\\");\\n    putenv((char*)\\"OMP_SCHEDULE=static\\");\\n}\\n\\nint main(int argc, char **argv) {\\n    setup_omp_env();\\n    if (argc != 6) {\\n        fprintf(stderr, \\"usage: %s <n> <m> <seed> <maxscore> <goal_ms>\\\\\\n\\", argv[0]);\\n        return 2;\\n    }\\n    uint32_t n = (uint32_t)strtoul(argv[1], nullptr, 10);\\n    uint32_t m = (uint32_t)strtoul(argv[2], nullptr, 10);\\n    uint32_t seed = (uint32_t)strtoul(argv[3], nullptr, 10);\\n    int maxscore = atoi(argv[4]);\\n    double goal_ms = atof(argv[5]);\\n\\n    std::vector<uint32_t> edges((size_t)m * 3);\\n    random_edges(n, m, seed, edges);\\n\\n    std::vector<uint64_t> mine(n, INF), want(n, INF);\\n    mine[0] = 0;\\n\\n    auto t0 = std::chrono::steady_clock::now();\\n    calculate(n, m, edges.data(), mine.data());\\n    auto t1 = std::chrono::steady_clock::now();\\n    double time_ms = std::chrono::duration<double, std::milli>(t1 - t0).count();\\n\\n    reference(n, m, edges, want);\\n\\n    size_t wrong = 0;\\n    uint32_t first_bad = 0;\\n    for (uint32_t i = 0; i < n; ++i) {\\n        if (mine[i] != want[i]) { if (wrong == 0) first_bad = i; ++wrong; }\\n    }\\n\\n    fflush(stdout);\\n    fprintf(stderr, \\"Time: %.6f seconds\\\\\\n\\", time_ms / 1000.0);\\n\\n    if (wrong != 0) {\\n        printf(\\"FOI_RESULT {\\\\\\"score\\\\\\":0,\\\\\\"maxScore\\\\\\":%d,\\\\\\"status\\\\\\":\\\\\\"wrong_answer\\\\\\",\\"\\n               \\"\\\\\\"message\\\\\\":\\\\\\"%zu/%u 个距离不对，首个是 dis[%u]=%llu（应为 %llu）\\\\\\"}\\\\\\n\\",\\n               maxscore, wrong, n, first_bad, (unsigned long long)mine[first_bad],\\n               (unsigned long long)want[first_bad]);\\n        return 0;\\n    }\\n\\n    double ratio = goal_ms > 0 ? goal_ms / (time_ms > 0 ? time_ms : goal_ms) : 0.0;\\n    if (ratio > 1.0) ratio = 1.0;\\n    int score = (int)round(exp(log((double)maxscore) * ratio));\\n    score = std::min(score, (int)maxscore);\\n    score = std::max(score, 0);\\n    printf(\\"FOI_RESULT {\\\\\\"score\\\\\\":%d,\\\\\\"maxScore\\\\\\":%d,\\\\\\"status\\\\\\":\\\\\\"%s\\\\\\",\\"\\n           \\"\\\\\\"message\\\\\\":\\\\\\"n=%u m=%u，耗时 %.1f ms（goal %.1f ms）\\\\\\"}\\\\\\n\\",\\n           score, maxscore, score >= maxscore ? \\"accepted\\" : \\"partial\\",\\n           n, m, time_ms, goal_ms);\\n    return 0;\\n}\\n", "language": "cpp"}	06136bc6fcca303c2a764d3f256665e3	interactive	\N	completed	{"score": 0, "status": "compile_error", "accepted": false, "maxScore": 50}	{"tests": [{"name": "1e6 点 / 2e6 边", "score": 0, "status": "compile_error", "maxScore": 10}, {"name": "1e7 点 / 2e7 边", "score": 0, "status": "compile_error", "maxScore": 20}, {"name": "1e7 点 / 1e7 边", "score": 0, "status": "compile_error", "maxScore": 20}], "message": "本题只提交实现：main() 由评测驱动提供，请不要自己定义"}	interactive-1.0.0	\N	2026-10-13 11:14:48.191+00	2026-10-13 11:14:49.487+00
sub_01M4T42E91Q7XDFFNXNJ6904DN	1	lu	kernel	{"source": "// The contestant file: implement my_solver here, and do NOT write main --\\n// driver.cpp already owns it. The judge overwrites this file with payload.source.\\n//\\n// What ships here is the naive implementation from the statement (single\\n// threaded, no blocking). It keeps the problem compilable out of the box and is\\n// the starting point for local testing. It is correct but slow: at N=2049 it\\n// already exceeds the 0.5 s limit, so submitting it unchanged scores 0 -- which\\n// is the whole point of scoring against the per-test full-mark time.\\n#include <cstdio>\\n#include <cstdlib>\\n#include <cmath>\\n\\nint mydgetrf(double *A,int *ipiv,int n)\\n{\\n    // LU decomposition with partial pivoting\\n    // A is stored in row-major format\\n    // On exit, A contains L (below diagonal with unit diagonal) and U (on and above diagonal)\\n    \\n    for (int k = 0; k < n; k++)\\n    {\\n        // Find pivot (max element in column k from row k to n-1)\\n        int pivot_row = k;\\n        double max_val = fabs(A[k * n + k]);\\n        \\n        for (int i = k + 1; i < n; i++)\\n        {\\n            double val = fabs(A[i * n + k]);\\n            if (val > max_val)\\n            {\\n                max_val = val;\\n                pivot_row = i;\\n            }\\n        }\\n        \\n        // Check for singularity\\n        if (max_val < 1e-14)\\n        {\\n            return 0; // Matrix is singular\\n        }\\n        \\n        // Record pivot\\n        ipiv[k] = pivot_row;\\n        \\n        // Swap rows k and pivot_row if needed\\n        if (pivot_row != k)\\n        {\\n            for (int j = 0; j < n; j++)\\n            {\\n                double tmp = A[k * n + j];\\n                A[k * n + j] = A[pivot_row * n + j];\\n                A[pivot_row * n + j] = tmp;\\n            }\\n        }\\n        \\n        // Compute multipliers and update submatrix\\n        for (int i = k + 1; i < n; i++)\\n        {\\n            // Compute multiplier L[i,k]\\n            A[i * n + k] = A[i * n + k] / A[k * n + k];\\n            \\n            // Update row i: A[i,k+1:n] -= L[i,k] * A[k,k+1:n]\\n            for (int j = k + 1; j < n; j++)\\n            {\\n                A[i * n + j] -= A[i * n + k] * A[k * n + j];\\n            }\\n        }\\n    }\\n    \\n    return 1;\\n}\\n\\nvoid mydtrsv(char UPLO,double *A,double *B,int n,int *ipiv)\\n{\\n    // Solve triangular system\\n    // A is in row-major format\\n    // UPLO='L': solve Lx=B (L has unit diagonal)\\n    // UPLO='U': solve Ux=B (U has non-unit diagonal)\\n    \\n    if (UPLO == 'L' || UPLO == 'l')\\n    {\\n        // Forward substitution for lower triangular system with unit diagonal\\n        // Apply pivoting first\\n        for (int i = 0; i < n; i++)\\n        {\\n            if (ipiv[i] != i)\\n            {\\n                double tmp = B[i];\\n                B[i] = B[ipiv[i]];\\n                B[ipiv[i]] = tmp;\\n            }\\n        }\\n        \\n        // Solve Lx=B where L has unit diagonal\\n        for (int i = 0; i < n; i++)\\n        {\\n            for (int j = 0; j < i; j++)\\n            {\\n                B[i] -= A[i * n + j] * B[j];\\n            }\\n            // Note: L[i,i] = 1, so no division needed\\n        }\\n    }\\n    else if (UPLO == 'U' || UPLO == 'u')\\n    {\\n        // Backward substitution for upper triangular system\\n        // Solve Ux=B\\n        for (int i = n - 1; i >= 0; i--)\\n        {\\n            for (int j = i + 1; j < n; j++)\\n            {\\n                B[i] -= A[i * n + j] * B[j];\\n            }\\n            B[i] /= A[i * n + i];\\n        }\\n    }\\n}\\n\\nvoid my_solver(int n, double *A, double *b)\\n{\\n    int *ipiv=(int*)malloc(n*sizeof(int));\\n    for (int i=0;i<n;i++)\\n        ipiv[i]=i;\\n    if (mydgetrf(A,ipiv,n)==0) \\n    {\\n        printf(\\"LU factorization failed: coefficient matrix is singular.\\\\n\\");\\n        free(ipiv);\\n        return;\\n    }\\n    mydtrsv('L',A,b,n,ipiv);\\n    mydtrsv('U',A,b,n,ipiv);\\n    free(ipiv);\\n}\\n", "language": "cpp"}	d2569c89313f23181b824c48d639e6e8	common	\N	completed	{"score": 0, "status": "time_limit_exceeded", "accepted": false, "maxScore": 50}	{"tests": [{"name": "N = 2049", "time": 2530, "score": 0, "memory": 112532, "status": "time_limit_exceeded", "message": "N=2049 用时 0.914350s，超过 0.7s 的限制", "maxScore": 10}, {"name": "N = 4096", "time": 10090, "score": 0, "memory": 134016, "status": "time_limit_exceeded", "message": "N=4096 用时 9.444473s，超过 7s 的限制", "maxScore": 20}, {"name": "N = 8192", "time": 53503, "score": 0, "memory": 0, "status": "time_limit_exceeded", "maxScore": 20}], "message": "N = 2049：N=2049 用时 0.914350s，超过 0.7s 的限制\\nN = 4096：N=4096 用时 9.444473s，超过 7s 的限制"}	common-1.0.0	\N	2026-10-13 07:54:12.134+00	2026-10-13 07:55:18.659+00
