sub_01M4TD052KSE1RDH3NA9M3WKG6	1	sssp-hpc	kernel	{"source": "#include <vector>\\n#include <cstdint>\\n#include <queue>\\n#include <omp.h>\\n\\nvoid calculate(uint32_t n, uint32_t m, uint32_t *edges, uint64_t *dis)\\n{\\n    struct edge { uint32_t to, w; };\\n    std::vector<edge> e(m);\\n    std::vector<uint32_t> deg(n, 0);\\n    std::vector<uint32_t> offset(n);\\n    std::vector<uint32_t> pos(m);\\n\\n#pragma omp parallel for\\n    for (uint32_t i = 0; i < m; ++i) {\\n        uint32_t u = edges[i * 3];\\n        pos[i] = __atomic_fetch_add(&deg[u], 1, __ATOMIC_RELAXED);\\n    }\\n    offset[0] = 0;\\n    for (int64_t i = 1; i < n; ++i) offset[i] = offset[i - 1] + deg[i - 1];\\n#pragma omp parallel for\\n    for (int64_t i = 0; i < m; ++i) {\\n        uint32_t u = edges[i * 3], v = edges[i * 3 + 1], w = edges[i * 3 + 2];\\n        e[offset[u] + pos[i]] = (edge){v, w};\\n    }\\n\\n    std::vector<uint8_t> vis(n, 0);\\n    std::vector<uint32_t> q;\\n    q.push_back(0);\\n    while (!q.empty()) {\\n        std::vector<uint32_t> next_q;\\n        std::fill(vis.begin(), vis.end(), 0);\\n#pragma omp parallel\\n        {\\n            std::vector<uint32_t> local_next_q;\\n#pragma omp for\\n            for (uint32_t i = 0; i < q.size(); ++i) {\\n                uint32_t u = q[i];\\n                for (uint32_t j = offset[u]; j < offset[u] + deg[u]; ++j) {\\n                    uint32_t v = e[j].to;\\n                    uint64_t new_dis = dis[u] + e[j].w;\\n                    uint64_t old_dis = dis[v];\\n                    while (new_dis < old_dis) {\\n                        if (__atomic_compare_exchange_n(&dis[v], &old_dis, new_dis, false, __ATOMIC_RELAXED, __ATOMIC_RELAXED)) {\\n                            if (__atomic_exchange_n(&vis[v], 1, __ATOMIC_RELAXED) == 0) {\\n                                local_next_q.push_back(v);\\n                                break;\\n                            }\\n                        }\\n                    }\\n                }\\n            }\\n#pragma omp critical\\n            { next_q.insert(next_q.end(), local_next_q.begin(), local_next_q.end()); }\\n        }\\n        q.swap(next_q);\\n    }\\n}", "language": "cpp"}	a7285d06b72e424e8b58b31a51d3b31f	interactive	\N	completed	{"score": 50, "status": "accepted", "accepted": true, "maxScore": 50}	{"tests": [{"name": "1e5 点 / 2e5 边", "time": 90, "score": 20, "memory": 14748, "status": "accepted", "message": "n=100000 m=200000，耗时 50.3 ms（goal 60.0 ms）", "maxScore": 20}, {"name": "1e5 点 / 1e6 边", "time": 150, "score": 20, "memory": 38516, "status": "accepted", "message": "n=100000 m=1000000，耗时 29.8 ms（goal 60.0 ms）", "maxScore": 20}, {"name": "1e6 点 / 2e6 边", "time": 970, "score": 10, "memory": 114796, "status": "accepted", "message": "n=1000000 m=2000000，耗时 125.0 ms（goal 200.0 ms）", "maxScore": 10}], "message": "1e5 点 / 2e5 边：n=100000 m=200000，耗时 50.3 ms（goal 60.0 ms）\\n1e5 点 / 1e6 边：n=100000 m=1000000，耗时 29.8 ms（goal 60.0 ms）\\n1e6 点 / 2e6 边：n=1000000 m=2000000，耗时 125.0 ms（goal 200.0 ms）"}	interactive-1.0.0	\N	2026-10-13 10:30:14.359+00	2026-10-13 10:30:18.916+00
